const exercisesData = [
    // --- PRINCIPIANTE (60 ejercicios) ---
    // IDs 1-20: Módulo 1 (Indentación, Intro, Variables, Operadores, Condicionales)
    { id: 1, lessonId: 1, title: 'Indentar un Método', description: '<strong>Qué hacer:</strong> El código del editor tiene todas las líneas pegadas al margen izquierdo. Reescríbelo con indentación correcta: 4 espacios por cada nivel de llaves <code>{ }</code> (<code>main</code> dentro de la clase y <code>println</code> dentro de <code>main</code>), sin cambiar las palabras <code>public class Ejemplo</code> ni <code>public static void main</code>.<br><strong>Salida esperada:</strong> <code>Hola</code>', difficulty: 'easy', starterCode: 'public class Ejemplo {\npublic static void main(String[] args) {\nSystem.out.println("Hola");\n}\n}', solution: 'public class Ejemplo {\n    public static void main(String[] args) {\n        System.out.println("Hola");\n    }\n}', hint: 'Cada nivel dentro de llaves { } debe tener 4 espacios de indentación. El método main está dentro de la clase (4 espacios), y el println está dentro del método (8 espacios).', validation: { checkIndentation: true, checkSyntax: true, requiredKeywords: ['public', 'class', 'static', 'void', 'main'], indentationSpaces: 4 } },
    { id: 2, lessonId: 1, title: 'Código con If-Else', description: '<strong>Qué hacer:</strong> Indenta este bloque <code>if-else</code>: el contenido de <code>if</code> y de <code>else</code> va con 4 espacios, y la llave de apertura <code>{</code> queda en la misma línea que <code>if</code> y <code>else</code>. Mantén la condición <code>edad &gt;= 18</code> y los dos <code>println</code>.<br><strong>Salida esperada:</strong> <code>Mayor</code> si <code>edad</code> vale 20 (con <code>edad</code> igual a 15 saldría <code>Menor</code>).', difficulty: 'medium', starterCode: 'if (edad >= 18) {\nSystem.out.println("Mayor");\n} else {\nSystem.out.println("Menor");\n}', solution: 'if (edad >= 18) {\n    System.out.println("Mayor");\n} else {\n    System.out.println("Menor");\n}', hint: 'El contenido dentro del if y del else debe estar indentado con 4 espacios. Las llaves de apertura van en la misma línea que if y else.', validation: { checkIndentation: true, requiredKeywords: ['if', 'else'] } },
    { id: 3, lessonId: 1, title: 'Múltiples Métodos', description: '<strong>Qué hacer:</strong> Indenta la clase <code>P</code>: sus métodos <code>a</code> y <code>b</code> van con 4 espacios, el contenido de cada método con 8 espacios y debe haber una línea vacía entre un método y el otro.<br><strong>Resultado esperado:</strong> la clase <code>P</code> con los métodos <code>void a()</code> (imprime <code>a</code>) y <code>void b()</code> (imprime <code>b</code>), bien indentada. No imprime nada por sí sola.', difficulty: 'medium', starterCode: 'class P {\nvoid a() {\nSystem.out.println("a");\n}\nvoid b() {\nSystem.out.println("b");\n}\n}', solution: 'class P {\n    void a() {\n        System.out.println("a");\n    }\n\n    void b() {\n        System.out.println("b");\n    }\n}', hint: 'Los métodos van indentados 4 espacios (están dentro de la clase). El contenido de cada método va indentado 8 espacios. Deja una línea vacía entre métodos.', validation: { checkIndentation: true, requiredKeywords: ['void'] } },
    { id: 4, lessonId: 1, title: 'Bucle Anidado', description: '<strong>Qué hacer:</strong> Haz dos cosas con este código: indéntalo (4 espacios por nivel: el <code>if</code> dentro del <code>for</code>, el <code>println</code> dentro del <code>if</code>) y agrega los espacios que faltan, es decir, uno después de <code>for</code> y de <code>if</code>, uno a cada lado de los operadores (<code>=</code>, <code>&lt;</code>, <code>%</code>, <code>==</code>) y uno después de cada <code>;</code> dentro del <code>for</code>.<br><strong>Salida esperada:</strong> <code>0</code>, <code>2</code> y <code>4</code>, cada uno en su línea (los números pares menores que 5).', difficulty: 'hard', starterCode: 'for(int i=0;i<5;i++){\nif(i%2==0){\nSystem.out.println(i);\n}\n}', solution: 'for (int i = 0; i < 5; i++) {\n    if (i % 2 == 0) {\n        System.out.println(i);\n    }\n}', hint: 'Debes hacer DOS cosas: 1) Indentar correctamente (if dentro del for = 4 espacios, println dentro del if = 8 espacios). 2) Agregar espacios: después de "for", alrededor de operadores (i = 0, i < 5, i++, i % 2 == 0).', validation: { checkIndentation: true, requiredKeywords: ['for', 'if'] } },
    { id: 5, lessonId: 2, title: 'Hola Mundo', description: '<strong>Qué hacer:</strong> Escribe un programa completo: una clase pública llamada <code>Hola</code> con el método <code>main</code> que muestre el texto <code>Hola, Java!</code> usando <code>System.out.println</code>. Respeta la coma y el signo de exclamación.<br><strong>Salida esperada:</strong> <code>Hola, Java!</code>', difficulty: 'easy', starterCode: '// Escribe tu solución aquí', solution: 'public class Hola {\n    public static void main(String[] args) {\n        System.out.println("Hola, Java!");\n    }\n}', hint: 'Crea una clase pública con el método main. Usa System.out.println() para imprimir "Hola, Java!" (con coma y signo de exclamación).', validation: { checkSyntax: true, mustContain: 'Hola, Java!' } },
    { id: 6, lessonId: 2, title: 'Múltiples Líneas', description: '<strong>Qué hacer:</strong> En el editor, reemplaza el comentario <code>//...</code> por dos instrucciones <code>System.out.println</code>: una que muestre <code>Línea 1</code> y otra que muestre <code>Línea 2</code>.<br><strong>Salida esperada:</strong> <code>Línea 1</code> y debajo <code>Línea 2</code>', difficulty: 'easy', starterCode: 'public class M {\npublic static void main(String[] args) {\n//...\n}\n}', hint: 'Reemplaza el comentario //... con dos llamadas a System.out.println(), una para cada línea. Cada println imprime en una línea nueva.', solution: 'System.out.println("Línea 1");\n        System.out.println("Línea 2");', validation: { mustContain: 'println', minLines: 2 } },
    { id: 7, lessonId: 2, title: 'Print vs Println', description: '<strong>Qué hacer:</strong> Escribe dos instrucciones seguidas: primero <code>System.out.print</code> con el texto <code>"Hola "</code> (con un espacio al final) y después <code>System.out.println</code> con el texto <code>"Mundo"</code>. Así ambas palabras quedan en la misma línea.<br><strong>Salida esperada:</strong> <code>Hola Mundo</code>', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'System.out.print("Hola ");\nSystem.out.println("Mundo");', hint: 'print() imprime sin salto de línea, println() imprime con salto de línea. Usa print para "Hola " (con espacio) y println para "Mundo".', validation: { requiredKeywords: ['print', 'println'] } },
    { id: 8, lessonId: 2, title: 'Printf', description: '<strong>Qué hacer:</strong> La variable <code>e</code> ya está declarada con el valor 25. Debajo, usa <code>System.out.printf</code> con el marcador <code>%d</code> para mostrar el texto <code>Edad: </code> seguido del valor de <code>e</code>.<br><strong>Salida esperada:</strong> <code>Edad: 25</code> (<code>printf</code> no agrega salto de línea por sí solo).', difficulty: 'hard', starterCode: 'int e = 25;', hint: 'printf permite formatear texto. Usa %d como marcador para números enteros: System.out.printf("Edad: %d", e);', solution: 'System.out.printf("Edad: %d", e);', validation: { requiredKeywords: ['printf', '%d'] } },
    { id: 9, lessonId: 3, title: 'Var Int', description: '<strong>Qué hacer:</strong> Declara una variable de tipo <code>int</code> llamada <code>edad</code> y asígnale el valor 25.<br><strong>Resultado esperado:</strong> una variable <code>int edad</code> con valor 25 (no hace falta imprimirla).', difficulty: 'easy', starterCode: '// Escribe tu solución aquí', solution: 'int edad = 25;', hint: 'Declara una variable entera con: tipo nombreVariable = valor; Ejemplo: int edad = 25;', validation: { requiredKeywords: ['int'], mustDeclare: 'edad' } },
    { id: 10, lessonId: 3, title: 'Var String', description: '<strong>Qué hacer:</strong> Declara una variable de tipo <code>String</code> llamada <code>nombre</code> con el valor <code>"Ana"</code> (texto entre comillas dobles).<br><strong>Resultado esperado:</strong> una variable <code>String nombre</code> con valor <code>"Ana"</code> (no hace falta imprimirla).', difficulty: 'easy', starterCode: '// Escribe tu solución aquí', solution: 'String nombre = "Ana";', hint: 'Los textos en Java se declaran con String (con S mayúscula). El valor va entre comillas dobles: String nombre = "Ana";', validation: { requiredKeywords: ['String'], mustDeclare: 'nombre' } },
    { id: 11, lessonId: 3, title: 'Casting', description: '<strong>Qué hacer:</strong> La variable <code>d</code> ya vale 9.99. Declara una variable <code>int i</code> y guarda en ella el valor de <code>d</code> convertido a entero con casting <code>(int)</code>.<br><strong>Resultado esperado:</strong> <code>i</code> vale <code>9</code> (el casting corta los decimales, no redondea).', difficulty: 'medium', starterCode: 'double d = 9.99;', solution: 'int i = (int) d;', hint: 'Para convertir un double a int, usa casting: int i = (int) nombreVariable; Esto trunca los decimales.', validation: { requiredKeywords: ['(int)'] } },
    { id: 12, lessonId: 3, title: 'PI Constante', description: '<strong>Qué hacer:</strong> Declara una constante de tipo <code>double</code> llamada <code>PI</code> (en mayúsculas) con el valor 3.14159, usando la palabra clave <code>final</code>.<br><strong>Resultado esperado:</strong> una constante <code>PI</code> de tipo <code>double</code> que vale 3.14159 y no se puede reasignar después (no hace falta imprimirla).', difficulty: 'hard', starterCode: '// Escribe tu solución aquí', solution: 'final double PI = 3.14159;', hint: 'Las constantes se declaran con final. Por convención, van en MAYÚSCULAS: final double PI = 3.14159;', validation: { requiredKeywords: ['final', 'PI'] } },
    { id: 13, lessonId: 4, title: 'Suma', description: '<strong>Qué hacer:</strong> Las variables <code>a</code> (10) y <code>b</code> (5) ya están declaradas. Declara una variable <code>int s</code> que guarde la suma de ambas con el operador <code>+</code>.<br><strong>Resultado esperado:</strong> <code>s</code> vale <code>15</code> (no hace falta imprimirla).', difficulty: 'easy', starterCode: 'int a=10, b=5;', solution: 'int s = a + b;', hint: 'Crea una variable para guardar el resultado de la suma: int s = a + b;', validation: { requiredKeywords: ['+'] } },
    { id: 14, lessonId: 4, title: 'Módulo', description: '<strong>Qué hacer:</strong> Declara una variable <code>int r</code> que guarde el resto de dividir 17 entre 2, usando el operador módulo <code>%</code>.<br><strong>Resultado esperado:</strong> <code>r</code> vale <code>1</code> (no hace falta imprimirla).', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'int r = 17 % 2;', hint: 'El operador % (módulo) devuelve el resto de una división: int r = 17 % 2; (resultado: 1)', validation: { requiredKeywords: ['%'] } },
    { id: 15, lessonId: 4, title: 'AND Lógico', description: '<strong>Qué hacer:</strong> Considera que <code>a</code> y <code>b</code> son variables <code>boolean</code> ya declaradas. Declara una variable <code>boolean result</code> que guarde el resultado de combinarlas con el operador lógico AND <code>&amp;&amp;</code>.<br><strong>Resultado esperado:</strong> <code>result</code> es <code>true</code> solo cuando <code>a</code> y <code>b</code> son <code>true</code>; en cualquier otro caso es <code>false</code>.', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'boolean result = a && b;', hint: 'El operador && (AND) devuelve true solo si ambas condiciones son verdaderas: boolean result = a && b;', validation: { requiredKeywords: ['&&'] } },
    { id: 16, lessonId: 4, title: 'Ternario', description: '<strong>Qué hacer:</strong> Considera que <code>e</code> es un <code>int</code> ya declarado (la edad). Declara una variable <code>String status</code> usando el operador ternario <code>? :</code>: debe valer <code>"A"</code> si <code>e &gt;= 18</code> y <code>"M"</code> en caso contrario.<br><strong>Resultado esperado:</strong> con <code>e</code> igual a 20, <code>status</code> vale <code>"A"</code>; con <code>e</code> igual a 15, vale <code>"M"</code>.', difficulty: 'hard', starterCode: '// Escribe tu solución aquí', solution: 'String status = (e >= 18) ? "A" : "M";', hint: 'El operador ternario es un if-else compacto: variable = (condición) ? valorSiTrue : valorSiFalse;', validation: { requiredKeywords: ['?', ':'] } },
    { id: 17, lessonId: 7, title: 'If simple', description: '<strong>Qué hacer:</strong> Considera que <code>x</code> es un <code>int</code> ya declarado (por ejemplo, 5). Dentro de las llaves del <code>if</code>, agrega una instrucción que imprima <code>P</code> con <code>System.out.println</code>, indentada con 4 espacios.<br><strong>Salida esperada:</strong> <code>P</code> si <code>x</code> es mayor que 0 (si <code>x</code> es 0 o negativo, no imprime nada).', difficulty: 'easy', starterCode: 'if(x > 0) { }', solution: 'if (x > 0) {\n    System.out.println("P");\n}', hint: 'Agrega System.out.println("P"); dentro de las llaves del if. Recuerda indentar con 4 espacios.', validation: { requiredKeywords: ['if'] } },
    { id: 18, lessonId: 7, title: 'If-Else Par', description: '<strong>Qué hacer:</strong> Considera que <code>n</code> es un <code>int</code> ya declarado. Escribe un <code>if-else</code> que imprima <code>Par</code> cuando <code>n % 2 == 0</code> y <code>Impar</code> en caso contrario.<br><strong>Salida esperada:</strong> <code>Par</code> si <code>n</code> vale 4; <code>Impar</code> si <code>n</code> vale 7.', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'if (n % 2 == 0) {\n    System.out.println("Par");\n} else {\n    System.out.println("Impar");\n}', hint: 'Un número es par si n % 2 == 0. Usa if-else: si es par imprime "Par", si no imprime "Impar".', validation: { requiredKeywords: ['if', 'else'] } },
    { id: 19, lessonId: 7, title: 'Else If Nota', description: '<strong>Qué hacer:</strong> Considera que <code>n</code> (un <code>int</code> con la nota) y <code>s</code> (un <code>String</code>) ya están declarados. Con una cadena <code>if</code> / <code>else if</code> / <code>else</code>, asigna a <code>s</code> el valor <code>"A"</code> si <code>n &gt;= 90</code>, <code>"B"</code> si <code>n &gt;= 70</code> y <code>"F"</code> en los demás casos.<br><strong>Resultado esperado:</strong> con <code>n</code> igual a 85, <code>s</code> vale <code>"B"</code>; con 95 vale <code>"A"</code>; con 40 vale <code>"F"</code>.', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'if (n >= 90) s="A"; else if (n >= 70) s="B"; else s="F";', hint: 'Usa if-else if-else para múltiples condiciones: si n >= 90 es "A", si n >= 70 es "B", si no es "F".', validation: { requiredKeywords: ['else if'] } },
    { id: 20, lessonId: 7, title: 'Condición Compleja', description: '<strong>Qué hacer:</strong> Considera que <code>a</code>, <code>b</code> y <code>c</code> son variables <code>boolean</code> ya declaradas. Escribe un <code>if</code> cuya condición sea verdadera cuando <code>a</code> es verdadera <strong>y además</strong> <code>b</code> o <code>c</code> lo es. Usa <code>&amp;&amp;</code>, <code>||</code> y paréntesis para agrupar. El cuerpo del <code>if</code> puede quedar vacío.<br><strong>Resultado esperado:</strong> un <code>if</code> con la condición <code>a &amp;&amp; (b || c)</code>.', difficulty: 'hard', starterCode: '// Escribe tu solución aquí', solution: 'if (a && (b || c)) { }', hint: 'Combina operadores lógicos: && (AND) y || (OR). Usa paréntesis para agrupar: if (a && (b || c))', validation: { requiredKeywords: ['&&', '||'] } },

    // IDs 21-40: Módulo 2 (Bucles, Switch, Scanner avanzado)
    { id: 21, lessonId: 9, title: 'While 1 a 5', description: '<strong>Qué hacer:</strong> La variable <code>i</code> ya está declarada con valor 1. Escribe un bucle <code>while</code> que, mientras <code>i &lt;= 5</code>, imprima <code>i</code> y luego lo incremente con <code>i++</code> (si no lo incrementas, el bucle será infinito).<br><strong>Salida esperada:</strong> <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code> y <code>5</code>, cada uno en su línea.', difficulty: 'easy', starterCode: 'int i = 1;', solution: 'while (i <= 5) {\n    System.out.println(i);\n    i++;\n}', hint: 'Usa while (condición) { }. Dentro del bucle imprime i y luego incrementa i++ para evitar bucle infinito.', validation: { requiredKeywords: ['while'] } },
    { id: 22, lessonId: 6, title: 'For Descendente', description: '<strong>Qué hacer:</strong> Escribe un bucle <code>for</code> que cuente hacia atrás: la variable <code>i</code> empieza en 10, el bucle sigue mientras <code>i &gt;= 1</code> y en cada vuelta baja con <code>i--</code>. En cada vuelta imprime <code>i</code>.<br><strong>Salida esperada:</strong> <code>10</code>, <code>9</code>, <code>8</code>, ... hasta <code>1</code>, cada número en su línea (10 líneas).', difficulty: 'easy', starterCode: '// Escribe tu solución aquí', solution: 'for (int i = 10; i >= 1; i--) {\n    System.out.println(i);\n}', hint: 'Inicia en 10, la condición es i >= 1, y decrementa con i--.', validation: { requiredKeywords: ['for'] } },
    { id: 23, lessonId: 9, title: 'Do-While', description: '<strong>Qué hacer:</strong> Declara <code>int i = 0</code> y escribe un bucle <code>do-while</code>: dentro del bloque imprime <code>i</code> y súmale 1 con <code>i++</code>; la condición del <code>while</code> es <code>i &lt; 3</code>.<br><strong>Salida esperada:</strong> <code>0</code>, <code>1</code> y <code>2</code>, cada uno en su línea.', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'int i = 0;\ndo {\n    System.out.println(i);\n    i++;\n} while (i < 3);', hint: 'do-while ejecuta el bloque primero y luego verifica la condición. Sintaxis: do { } while (condición);', validation: { requiredKeywords: ['do', 'while'] } },
    { id: 24, lessonId: 10, title: 'Break en Bucle', description: '<strong>Qué hacer:</strong> Dentro del <code>for</code> del editor (<code>i</code> va de 1 a 10), primero comprueba con un <code>if</code> si <code>i == 5</code> y, en ese caso, sal del bucle con <code>break</code>; después imprime <code>i</code>.<br><strong>Salida esperada:</strong> <code>1</code>, <code>2</code>, <code>3</code> y <code>4</code>, cada uno en su línea (el 5 ya no se imprime).', difficulty: 'medium', starterCode: 'for (int i = 1; i <= 10; i++) {\n    // ...\n}', solution: 'for (int i = 1; i <= 10; i++) {\n    if (i == 5) break;\n    System.out.println(i);\n}', hint: 'Usa break para salir del bucle. Verifica con if si i == 5 y ejecuta break.', validation: { requiredKeywords: ['break'] } },
    { id: 25, lessonId: 10, title: 'Continue en Bucle', description: '<strong>Qué hacer:</strong> Escribe un bucle <code>for</code> con <code>i</code> de 1 a 5 (<code>i &lt;= 5</code>). Dentro, si <code>i</code> es par (<code>i % 2 == 0</code>), usa <code>continue</code> para saltar esa vuelta; en las demás, imprime <code>i</code>.<br><strong>Salida esperada:</strong> <code>1</code>, <code>3</code> y <code>5</code>, cada uno en su línea.', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'for (int i = 1; i <= 5; i++) {\n    if (i % 2 == 0) continue;\n    System.out.println(i);\n}', hint: 'continue salta a la siguiente iteración. Si i es par (i % 2 == 0), usa continue para saltarlo.', validation: { requiredKeywords: ['continue'] } },
    { id: 26, lessonId: 6, title: 'Bucle Anidado Tabla', description: '<strong>Qué hacer:</strong> Con dos bucles <code>for</code> anidados, imprime las tablas de multiplicar del 2 y del 3 hasta el 5. El bucle externo recorre <code>i</code> de 2 a 3 y el interno recorre <code>j</code> de 1 a 5. En cada vuelta imprime una línea con el formato <code>i x j = resultado</code>.<br><strong>Salida esperada:</strong> 10 líneas, desde <code>2 x 1 = 2</code> hasta <code>2 x 5 = 10</code> y luego desde <code>3 x 1 = 3</code> hasta <code>3 x 5 = 15</code>.', difficulty: 'hard', starterCode: '// Escribe tu solución aquí', solution: 'for (int i = 2; i <= 3; i++) {\n    for (int j = 1; j <= 5; j++) {\n        System.out.println(i + " x " + j + " = " + (i * j));\n    }\n}', hint: 'Usa dos bucles for anidados. El externo para las tablas (2 y 3), el interno para los multiplicadores (1 a 5).', validation: { requiredKeywords: ['for'] } },
    { id: 27, lessonId: 9, title: 'Suma con While', description: '<strong>Qué hacer:</strong> Declara <code>int suma = 0</code> e <code>int i = 1</code>. Con un bucle <code>while</code> mientras <code>i &lt;= 100</code>, acumula en <code>suma</code> el valor de <code>i</code> usando <code>+=</code> e incrementa <code>i</code>. Al terminar, imprime <code>suma</code>.<br><strong>Salida esperada:</strong> <code>5050</code>', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'int suma = 0;\nint i = 1;\nwhile (i <= 100) {\n    suma += i;\n    i++;\n}\nSystem.out.println(suma);', hint: 'Inicializa suma en 0. En cada iteración suma += i. No olvides incrementar i.', validation: { requiredKeywords: ['while', '+='] } },
    { id: 28, lessonId: 6, title: 'For-Each Array', description: '<strong>Qué hacer:</strong> El array <code>nums</code> ya está declarado con los valores 1 a 5. Recórrelo con un bucle for-each (<code>for (int n : nums)</code>) e imprime cada elemento.<br><strong>Salida esperada:</strong> <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code> y <code>5</code>, cada uno en su línea.', difficulty: 'easy', starterCode: 'int[] nums = {1, 2, 3, 4, 5};', solution: 'for (int n : nums) {\n    System.out.println(n);\n}', hint: 'for-each: for (tipo variable : array) { }. Ejemplo: for (int n : nums)', validation: { requiredKeywords: ['for', ':'] } },
    { id: 29, lessonId: 8, title: 'Switch Día Semana', description: '<strong>Qué hacer:</strong> Considera que <code>int dia = 3;</code> ya está declarada. Escribe un <code>switch (dia)</code> clásico con <code>case 1</code> (imprime <code>Lunes</code>), <code>case 2</code> (<code>Martes</code>), <code>case 3</code> (<code>Miércoles</code>) y un <code>default</code> que imprima <code>Otro día</code>. Cierra cada caso con <code>break</code>.<br><strong>Salida esperada:</strong> <code>Miércoles</code> (porque <code>dia</code> vale 3).', difficulty: 'easy', starterCode: 'int dia = 3;', solution: 'switch (dia) {\n    case 1: System.out.println("Lunes"); break;\n    case 2: System.out.println("Martes"); break;\n    case 3: System.out.println("Miércoles"); break;\n    default: System.out.println("Otro día");\n}', hint: 'switch (variable) { case valor: código; break; }. No olvides break para evitar fall-through.', validation: { requiredKeywords: ['switch', 'case', 'break'] } },
    { id: 30, lessonId: 8, title: 'Switch sin Break', description: '<strong>Qué hacer:</strong> Declara <code>int mes = 2</code> y escribe un <code>switch (mes)</code> clásico donde los casos 12, 1 y 2 compartan el mismo código, sin <code>break</code> entre ellos (fall-through), y terminen imprimiendo <code>Verano</code> seguido de <code>break</code>. El <code>default</code> imprime <code>Otra estación</code>.<br><strong>Salida esperada:</strong> <code>Verano</code>', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'int mes = 2;\nswitch (mes) {\n    case 12:\n    case 1:\n    case 2:\n        System.out.println("Verano");\n        break;\n    default:\n        System.out.println("Otra estación");\n}', hint: 'Puedes omitir break para que varios cases ejecuten el mismo código (fall-through).', validation: { requiredKeywords: ['switch', 'case'] } },
    { id: 31, lessonId: 8, title: 'Switch con String', description: '<strong>Qué hacer:</strong> La variable <code>color</code> ya vale <code>"rojo"</code>. Escribe un <code>switch (color)</code> con <code>case "rojo"</code> (imprime <code>Peligro</code>), <code>case "verde"</code> (imprime <code>Seguro</code>) y un <code>default</code> que imprima <code>Desconocido</code>. Usa <code>break</code> en cada caso.<br><strong>Salida esperada:</strong> <code>Peligro</code>', difficulty: 'medium', starterCode: 'String color = "rojo";', solution: 'switch (color) {\n    case "rojo":\n        System.out.println("Peligro");\n        break;\n    case "verde":\n        System.out.println("Seguro");\n        break;\n    default:\n        System.out.println("Desconocido");\n}', hint: 'Desde Java 7, switch acepta String. Usa comillas dobles en los cases.', validation: { requiredKeywords: ['switch', 'case'] } },
    { id: 32, lessonId: 8, title: 'Switch Expression', description: '<strong>Qué hacer:</strong> La variable <code>nota</code> ya vale 8. Declara <code>String resultado</code> con una <em>switch expression</em> con flechas <code>-&gt;</code>: <code>case 10, 9</code> da <code>"Excelente"</code>, <code>case 8, 7</code> da <code>"Bueno"</code> y <code>default</code> da <code>"Regular"</code>. Termina la expresión con <code>;</code>.<br><strong>Resultado esperado:</strong> <code>resultado</code> vale <code>"Bueno"</code> (no hace falta imprimirlo).', difficulty: 'hard', starterCode: 'int nota = 8;', solution: 'String resultado = switch (nota) {\n    case 10, 9 -> "Excelente";\n    case 8, 7 -> "Bueno";\n    default -> "Regular";\n};', hint: 'Switch expression (Java 14+): variable = switch (x) { case a -> valor; };', validation: { requiredKeywords: ['switch', '->'] } },
    { id: 33, lessonId: 5, title: 'Scanner Leer Int', description: '<strong>Qué hacer:</strong> El <code>import</code> ya está en el editor. Crea un <code>Scanner</code> llamado <code>sc</code> con <code>System.in</code>, muestra con <code>System.out.print</code> el texto <code>Edad: </code> y lee un entero con <code>nextInt()</code> guardándolo en la variable <code>edad</code>.<br><strong>Salida esperada:</strong> <code>Edad: </code> y el programa queda esperando que escribas un número (si escribes 30, <code>edad</code> vale 30).', difficulty: 'easy', starterCode: 'import java.util.Scanner;', solution: 'Scanner sc = new Scanner(System.in);\nSystem.out.print("Edad: ");\nint edad = sc.nextInt();', hint: 'Crea Scanner: Scanner sc = new Scanner(System.in); Luego usa sc.nextInt() para leer enteros.', validation: { requiredKeywords: ['Scanner', 'nextInt'] } },
    { id: 34, lessonId: 5, title: 'Scanner Leer String', description: '<strong>Qué hacer:</strong> El <code>import</code> ya está en el editor. Crea un <code>Scanner</code> llamado <code>sc</code>, muestra con <code>System.out.print</code> el texto <code>Nombre: </code> y lee una línea completa con <code>nextLine()</code> en la variable <code>nombre</code> (así se aceptan espacios, como en <code>Ana Pérez</code>).<br><strong>Salida esperada:</strong> <code>Nombre: </code> y el programa queda esperando que escribas tu nombre.', difficulty: 'easy', starterCode: 'import java.util.Scanner;', solution: 'Scanner sc = new Scanner(System.in);\nSystem.out.print("Nombre: ");\nString nombre = sc.nextLine();', hint: 'nextLine() lee toda la línea incluyendo espacios. next() solo lee una palabra.', validation: { requiredKeywords: ['Scanner', 'nextLine'] } },
    { id: 35, lessonId: 5, title: 'Scanner Múltiples Datos', description: '<strong>Qué hacer:</strong> Crea un <code>Scanner</code> llamado <code>sc</code>. Pide primero el nombre (<code>print</code> de <code>Nombre: </code>, lectura con <code>nextLine()</code> en <code>nombre</code>) y después la edad (<code>print</code> de <code>Edad: </code>, lectura con <code>nextInt()</code> en <code>edad</code>).<br><strong>Salida esperada:</strong> <code>Nombre: </code> y, tras escribir <code>Ana Pérez</code> y Enter, <code>Edad: </code> (si escribes 30, <code>edad</code> vale 30).', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'Scanner sc = new Scanner(System.in);\nSystem.out.print("Nombre: ");\nString nombre = sc.nextLine();\nSystem.out.print("Edad: ");\nint edad = sc.nextInt();', hint: 'Puedes llamar a nextLine() y nextInt() en secuencia para leer diferentes tipos de datos.', validation: { requiredKeywords: ['Scanner', 'nextLine', 'nextInt'] } },
    { id: 36, lessonId: 5, title: 'Scanner Validar Entrada', description: '<strong>Qué hacer:</strong> Crea un <code>Scanner</code> llamado <code>sc</code>. Con un <code>if</code> que use <code>sc.hasNextInt()</code>: si lo siguiente es un entero, léelo con <code>nextInt()</code> en <code>num</code> e imprime <code>Número: </code> seguido del valor; si no, en el <code>else</code> imprime <code>No es número</code>.<br><strong>Salida esperada:</strong> si escribes <code>42</code>: <code>Número: 42</code>; si escribes <code>hola</code>: <code>No es número</code>.', difficulty: 'hard', starterCode: 'import java.util.Scanner;', solution: 'Scanner sc = new Scanner(System.in);\nif (sc.hasNextInt()) {\n    int num = sc.nextInt();\n    System.out.println("Número: " + num);\n} else {\n    System.out.println("No es número");\n}', hint: 'Usa hasNextInt() para verificar si la entrada es un entero antes de leerla con nextInt().', validation: { requiredKeywords: ['hasNextInt'] } },
    { id: 37, lessonId: 5, title: 'Scanner en Bucle', description: '<strong>Qué hacer:</strong> Crea un <code>Scanner</code> llamado <code>sc</code>, declara <code>int num</code> y escribe un bucle <code>do-while</code>: en cada vuelta imprime con <code>print</code> el texto <code>Número (0 para salir): </code> y lee un entero con <code>nextInt()</code> en <code>num</code>. El bucle se repite mientras <code>num != 0</code>.<br><strong>Salida esperada:</strong> <code>Número (0 para salir): </code> se repite hasta que escribas 0 (si escribes 5, 3 y 0, el texto aparece tres veces).', difficulty: 'medium', starterCode: '// Escribe tu solución aquí', solution: 'Scanner sc = new Scanner(System.in);\nint num;\ndo {\n    System.out.print("Número (0 para salir): ");\n    num = sc.nextInt();\n} while (num != 0);', hint: 'Usa do-while para leer al menos una vez. La condición es num != 0 para continuar.', validation: { requiredKeywords: ['Scanner', 'do', 'while'] } },
    { id: 38, lessonId: 5, title: 'Scanner Cerrar', description: '<strong>Qué hacer:</strong> El editor ya crea el <code>Scanner</code> <code>sc</code> y lee un entero en <code>num</code>. Agrega al final la instrucción que cierra el <code>Scanner</code> con <code>close()</code>.<br><strong>Resultado esperado:</strong> el código termina con <code>sc.close();</code>. No imprime nada.', difficulty: 'easy', starterCode: 'Scanner sc = new Scanner(System.in);\nint num = sc.nextInt();', solution: 'Scanner sc = new Scanner(System.in);\nint num = sc.nextInt();\nsc.close();', hint: 'Siempre cierra Scanner con sc.close() para liberar recursos.', validation: { requiredKeywords: ['close'] } },
    { id: 39, lessonId: 5, title: 'Scanner Try-With-Resources', description: '<strong>Qué hacer:</strong> Usa <code>try-with-resources</code>: abre un <code>try (Scanner sc = new Scanner(System.in)) { ... }</code>. Dentro, imprime <code>Número: </code> con <code>print</code>, lee un entero con <code>nextInt()</code> en <code>num</code> e imprime <code>Leído: </code> seguido del valor.<br><strong>Salida esperada:</strong> si escribes <code>42</code>: <code>Número: </code> y luego <code>Leído: 42</code>.', difficulty: 'hard', starterCode: '// Escribe tu solución aquí', solution: 'try (Scanner sc = new Scanner(System.in)) {\n    System.out.print("Número: ");\n    int num = sc.nextInt();\n    System.out.println("Leído: " + num);\n}', hint: 'try-with-resources cierra automáticamente: try (Scanner sc = new Scanner(...)) { }', validation: { requiredKeywords: ['try', 'Scanner'] } },
    { id: 40, lessonId: 5, title: 'Scanner Leer Double', description: '<strong>Qué hacer:</strong> El <code>import</code> ya está en el editor. Crea un <code>Scanner</code> llamado <code>sc</code>, muestra con <code>print</code> el texto <code>Precio: </code> y lee un decimal con <code>nextDouble()</code> guardándolo en la variable <code>precio</code> (de tipo <code>double</code>).<br><strong>Salida esperada:</strong> <code>Precio: </code> y el programa queda esperando un número decimal (si escribes 3.5, <code>precio</code> vale 3.5).', difficulty: 'easy', starterCode: 'import java.util.Scanner;', solution: 'Scanner sc = new Scanner(System.in);\nSystem.out.print("Precio: ");\ndouble precio = sc.nextDouble();', hint: 'Usa nextDouble() para leer números decimales (double).', validation: { requiredKeywords: ['Scanner', 'nextDouble'] } },

    // IDs 41-60: Módulo 3 (Arrays, Matrices, Strings, StringBuilder, Métodos)
    { id: 41, lessonId: 11, title: 'Declarar Array', description: '<strong>Qué hacer:</strong> Declara una variable llamada <code>nums</code> que sea un array de enteros (<code>int[]</code>) con 5 posiciones, creado con la palabra <code>new</code>.<br><strong>Resultado esperado:</strong> una línea de código que crea <code>nums</code> con tamaño 5. No imprime nada.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'int[] nums = new int[5];', hint: 'Sintaxis: tipo[] nombre = new tipo[tamaño]; Ejemplo: int[] nums = new int[5];', validation: { requiredKeywords: ['int[]', 'new'] } },
    { id: 42, lessonId: 11, title: 'Inicializar Array', description: '<strong>Qué hacer:</strong> Declara un array de enteros (<code>int[]</code>) llamado <code>nums</code> e inicialízalo directamente con los valores 1, 2 y 3 usando llaves.<br><strong>Resultado esperado:</strong> <code>nums</code> contiene <code>{1, 2, 3}</code>. No imprime nada.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'int[] nums = {1, 2, 3};', hint: 'Puedes inicializar con valores: int[] nums = {valor1, valor2, valor3};', validation: { requiredKeywords: ['int[]'] } },
    { id: 43, lessonId: 11, title: 'Acceder Elemento', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya está declarado como <code>{10, 20, 30}</code>. Imprime con <code>System.out.println</code> el primer elemento, accediendo con su índice entre corchetes.<br><strong>Salida esperada:</strong> <code>10</code>', difficulty: 'easy', starterCode: 'int[] nums = {10, 20, 30};', solution: 'System.out.println(nums[0]);', hint: 'Los arrays empiezan en índice 0. Accede con nombreArray[índice].', validation: { requiredKeywords: ['[0]'] } },
    { id: 44, lessonId: 11, title: 'Modificar Elemento', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya está declarado como <code>{10, 20, 30}</code>. Cambia el segundo elemento por el valor 50 con una asignación usando su índice entre corchetes.<br><strong>Resultado esperado:</strong> después de tu línea, <code>nums</code> vale <code>{10, 50, 30}</code>. No hace falta imprimir nada.', difficulty: 'easy', starterCode: 'int[] nums = {10, 20, 30};', solution: 'nums[1] = 50;', hint: 'Para modificar: nombreArray[índice] = nuevoValor; El segundo elemento está en índice 1.', validation: { requiredKeywords: ['[1]', '='] } },
    { id: 45, lessonId: 11, title: 'Longitud Array', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya está declarado como <code>{1, 2, 3, 4, 5}</code>. Imprime con <code>System.out.println</code> cuántos elementos tiene, usando la propiedad <code>length</code> del array.<br><strong>Salida esperada:</strong> <code>5</code>', difficulty: 'easy', starterCode: 'int[] nums = {1, 2, 3, 4, 5};', solution: 'System.out.println(nums.length);', hint: 'Usa .length (sin paréntesis) para obtener el tamaño: nums.length', validation: { requiredKeywords: ['length'] } },
    { id: 46, lessonId: 11, title: 'Recorrer Array', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya está declarado como <code>{1, 2, 3, 4, 5}</code>. Con un bucle <code>for</code> que use <code>nums.length</code>, imprime cada elemento en su propia línea.<br><strong>Salida esperada:</strong> cinco líneas: <code>1</code>, <code>2</code>, <code>3</code>, <code>4</code> y <code>5</code>.', difficulty: 'medium', starterCode: 'int[] nums = {1, 2, 3, 4, 5};', solution: 'for (int i = 0; i < nums.length; i++) {\n    System.out.println(nums[i]);\n}', hint: 'Usa for desde 0 hasta nums.length-1. Accede a cada elemento con nums[i].', validation: { requiredKeywords: ['for', 'length'] } },
    { id: 47, lessonId: 11, title: 'Suma Array', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya está declarado como <code>{5, 10, 15, 20}</code>. Declara una variable <code>suma</code> en 0, recorre el array con un bucle <code>for</code> acumulando cada valor con <code>+=</code>, e imprime el total al final.<br><strong>Salida esperada:</strong> <code>50</code>', difficulty: 'medium', starterCode: 'int[] nums = {5, 10, 15, 20};', solution: 'int suma = 0;\nfor (int n : nums) {\n    suma += n;\n}\nSystem.out.println(suma);', hint: 'Inicializa suma en 0. Usa for-each para recorrer y suma += n en cada iteración.', validation: { requiredKeywords: ['for', '+='] } },
    { id: 48, lessonId: 11, title: 'Máximo en Array', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya está declarado como <code>{3, 7, 2, 9, 1}</code>. Guarda en una variable <code>max</code> el primer elemento, recorre el array con un bucle <code>for</code> y usa un <code>if</code> para actualizar <code>max</code> cuando encuentres un valor mayor. Imprime <code>max</code> al final.<br><strong>Salida esperada:</strong> <code>9</code>', difficulty: 'hard', starterCode: 'int[] nums = {3, 7, 2, 9, 1};', solution: 'int max = nums[0];\nfor (int n : nums) {\n    if (n > max) max = n;\n}\nSystem.out.println(max);', hint: 'Inicializa max con el primer elemento. Recorre y actualiza max si encuentras uno mayor.', validation: { requiredKeywords: ['for', 'if'] } },
    { id: 49, lessonId: 12, title: 'Matriz 2x2', description: '<strong>Qué hacer:</strong> Declara una variable llamada <code>matriz</code> de tipo <code>int[][]</code> con 2 filas y 2 columnas, creada con la palabra <code>new</code>.<br><strong>Resultado esperado:</strong> una línea de código que crea <code>matriz</code> de tamaño 2x2. No imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'int[][] matriz = new int[2][2];', hint: 'Matriz: tipo[][] nombre = new tipo[filas][columnas]; Ejemplo: int[][] matriz = new int[2][2];', validation: { requiredKeywords: ['int[][]', 'new'] } },
    { id: 50, lessonId: 12, title: 'Inicializar Matriz', description: '<strong>Qué hacer:</strong> Declara una variable <code>matriz</code> de tipo <code>int[][]</code> e inicialízala con llaves anidadas: la primera fila con 1 y 2, la segunda fila con 3 y 4.<br><strong>Resultado esperado:</strong> <code>matriz</code> contiene <code>{{1, 2}, {3, 4}}</code>. No imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'int[][] matriz = {{1, 2}, {3, 4}};', hint: 'Inicializa con llaves anidadas: int[][] m = {{fila1}, {fila2}};', validation: { requiredKeywords: ['int[][]'] } },
    { id: 51, lessonId: 12, title: 'Acceder Matriz', description: '<strong>Qué hacer:</strong> Considera que <code>m</code> ya está declarada como <code>{{1, 2}, {3, 4}}</code>. Imprime con <code>System.out.println</code> el elemento de la fila 1, columna 0, usando dos índices: <code>m[fila][columna]</code>.<br><strong>Salida esperada:</strong> <code>3</code>', difficulty: 'medium', starterCode: 'int[][] m = {{1, 2}, {3, 4}};', solution: 'System.out.println(m[1][0]);', hint: 'Accede con matriz[fila][columna]. [1][0] es fila 1, columna 0 (valor: 3).', validation: { requiredKeywords: ['[1][0]'] } },
    { id: 52, lessonId: 12, title: 'Recorrer Matriz', description: '<strong>Qué hacer:</strong> Considera que <code>m</code> ya está declarada como <code>{{1, 2}, {3, 4}}</code>. Con dos bucles <code>for</code> anidados (filas con <code>m.length</code>, columnas con <code>m[i].length</code>) imprime cada número seguido de un espacio y, al terminar cada fila, un salto de línea.<br><strong>Salida esperada:</strong> dos líneas: <code>1 2 </code> y <code>3 4 </code> (cada número va seguido de un espacio).', difficulty: 'hard', starterCode: 'int[][] m = {{1, 2}, {3, 4}};', solution: 'for (int i = 0; i < m.length; i++) {\n    for (int j = 0; j < m[i].length; j++) {\n        System.out.print(m[i][j] + " ");\n    }\n    System.out.println();\n}', hint: 'Usa dos bucles anidados: externo para filas (m.length), interno para columnas (m[i].length).', validation: { requiredKeywords: ['for'] } },
    { id: 53, lessonId: 13, title: 'Longitud String', description: '<strong>Qué hacer:</strong> Considera que <code>texto</code> ya vale <code>"Hola"</code>. Imprime con <code>System.out.println</code> su cantidad de caracteres usando el método <code>length()</code>.<br><strong>Salida esperada:</strong> <code>4</code>', difficulty: 'easy', starterCode: 'String texto = "Hola";', solution: 'System.out.println(texto.length());', hint: 'Usa .length() (con paréntesis) para Strings: texto.length()', validation: { requiredKeywords: ['length()'] } },
    { id: 54, lessonId: 13, title: 'Concatenar Strings', description: '<strong>Qué hacer:</strong> Considera que <code>a</code> vale <code>"Hola"</code> y <code>b</code> vale <code>"Mundo"</code>. Crea un String <code>c</code> uniendo <code>a</code>, un espacio y <code>b</code> con el operador <code>+</code>, e imprímelo.<br><strong>Salida esperada:</strong> <code>Hola Mundo</code>', difficulty: 'easy', starterCode: 'String a = "Hola";\nString b = "Mundo";', solution: 'String c = a + " " + b;\nSystem.out.println(c);', hint: 'Concatena con +: String c = a + " " + b; (resultado: "Hola Mundo")', validation: { requiredKeywords: ['+'] } },
    { id: 55, lessonId: 13, title: 'Mayúsculas', description: '<strong>Qué hacer:</strong> Considera que <code>texto</code> ya vale <code>"hola"</code>. Guarda en una variable String <code>mayus</code> el resultado de llamar a <code>toUpperCase()</code> sobre <code>texto</code>, e imprime <code>mayus</code>.<br><strong>Salida esperada:</strong> <code>HOLA</code>', difficulty: 'easy', starterCode: 'String texto = "hola";', solution: 'String mayus = texto.toUpperCase();\nSystem.out.println(mayus);', hint: 'Usa .toUpperCase() para convertir a mayúsculas. Retorna un nuevo String.', validation: { requiredKeywords: ['toUpperCase'] } },
    { id: 56, lessonId: 13, title: 'Substring', description: '<strong>Qué hacer:</strong> Considera que <code>texto</code> ya vale <code>"Hola Mundo"</code>. Guarda en una variable String <code>sub</code> los caracteres desde la posición 0 hasta la 3 (el final de <code>substring</code> no se incluye) e imprime <code>sub</code>.<br><strong>Salida esperada:</strong> <code>Hola</code>', difficulty: 'medium', starterCode: 'String texto = "Hola Mundo";', solution: 'String sub = texto.substring(0, 4);\nSystem.out.println(sub);', hint: 'substring(inicio, fin) extrae desde inicio hasta fin-1. substring(0, 4) extrae "Hola".', validation: { requiredKeywords: ['substring'] } },
    { id: 57, lessonId: 13, title: 'Comparar Strings', description: '<strong>Qué hacer:</strong> Considera que <code>a</code> y <code>b</code> ya valen <code>"Hola"</code>. Con un <code>if</code> y el método <code>equals</code> (no uses <code>==</code>), imprime un mensaje si ambos textos son iguales.<br><strong>Salida esperada:</strong> <code>Iguales</code>', difficulty: 'medium', starterCode: 'String a = "Hola";\nString b = "Hola";', solution: 'if (a.equals(b)) {\n    System.out.println("Iguales");\n}', hint: 'NUNCA uses == para Strings. Usa .equals(): if (a.equals(b))', validation: { requiredKeywords: ['equals'] } },
    { id: 58, lessonId: 14, title: 'StringBuilder Append', description: '<strong>Qué hacer:</strong> Crea un <code>StringBuilder</code> llamado <code>sb</code>. Con tres llamadas a <code>append</code> agrega <code>"Hola"</code>, <code>" "</code> y <code>"Mundo"</code>, y luego imprime el resultado usando <code>toString()</code>.<br><strong>Salida esperada:</strong> <code>Hola Mundo</code>', difficulty: 'medium', starterCode: '// Escribe tu programa completo aquí', solution: 'StringBuilder sb = new StringBuilder();\nsb.append("Hola");\nsb.append(" ");\nsb.append("Mundo");\nSystem.out.println(sb.toString());', hint: 'StringBuilder es mutable. Usa .append() para agregar y .toString() para convertir a String.', validation: { requiredKeywords: ['StringBuilder', 'append'] } },
    { id: 59, lessonId: 15, title: 'Método Sin Retorno', description: '<strong>Qué hacer:</strong> Define un método <code>public static void saludar()</code>, sin parámetros, que imprima el texto <code>Hola</code> con <code>System.out.println</code>.<br><strong>Resultado esperado:</strong> existe el método <code>saludar</code> de tipo <code>void</code>; al llamarlo, imprime <code>Hola</code>. No hace falta llamarlo.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'public static void saludar() {\n    System.out.println("Hola");\n}', hint: 'Método sin retorno: public static void nombreMetodo() { código }', validation: { requiredKeywords: ['void', 'saludar'] } },
    { id: 60, lessonId: 15, title: 'Método Con Retorno', description: '<strong>Qué hacer:</strong> Define un método <code>public static int sumar(int a, int b)</code> que reciba dos enteros y devuelva su suma usando <code>return</code>.<br><strong>Resultado esperado:</strong> existe el método <code>sumar</code>; por ejemplo, <code>sumar(2, 3)</code> devuelve <code>5</code>. El método no imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'public static int sumar(int a, int b) {\n    return a + b;\n}', hint: 'Método con retorno: public static tipoRetorno nombre(parámetros) { return valor; }', validation: { requiredKeywords: ['return'] } },

    // IDs 61-120: INTERMEDIO (POO, Colecciones)
    // IDs 61-80: POO Básico
    { id: 61, lessonId: 16, title: 'Clase Simple', description: '<strong>Resultado esperado:</strong> una clase pública llamada <code>Persona</code> con dos atributos: <code>nombre</code> de tipo <code>String</code> y <code>edad</code> de tipo <code>int</code>. No necesita <code>main</code> ni imprime nada.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'public class Persona {\n    String nombre;\n    int edad;\n}', hint: 'Una clase es un molde. Define atributos dentro: public class NombreClase { tipo atributo; }', validation: { requiredKeywords: ['class', 'Persona'] } },
    { id: 62, lessonId: 17, title: 'Constructor', description: '<strong>Resultado esperado:</strong> dentro de la clase <code>Persona</code> añade un constructor público <code>Persona(String nombre, int edad)</code> que use <code>this</code> para guardar cada parámetro en el atributo del mismo nombre. No imprime nada.', difficulty: 'medium', starterCode: 'public class Persona {\n    String nombre;\n    int edad;\n}', solution: 'public Persona(String nombre, int edad) {\n    this.nombre = nombre;\n    this.edad = edad;\n}', hint: 'Constructor: public NombreClase(parámetros) { this.atributo = parámetro; }', validation: { requiredKeywords: ['Persona', 'this'] } },
    { id: 63, lessonId: 16, title: 'Crear Objeto', description: '<strong>Resultado esperado:</strong> una línea que cree un objeto con <code>new</code> y lo guarde en una variable <code>p</code> de tipo <code>Persona</code>, pasando <code>"Ana"</code> como nombre y <code>25</code> como edad. Considera que la clase <code>Persona</code> ya existe con ese constructor. No imprime nada.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'Persona p = new Persona("Ana", 25);', hint: 'Crear objeto: NombreClase variable = new NombreClase(argumentos);', validation: { requiredKeywords: ['new', 'Persona'] } },
    { id: 64, lessonId: 16, title: 'Acceder Atributo', description: '<strong>Qué hacer:</strong> el objeto <code>p</code> ya está creado (nombre <code>"Ana"</code>, edad 25). Imprime con <code>System.out.println</code> el atributo <code>nombre</code> accediendo con el punto, es decir, <code>p.nombre</code>.<br><strong>Salida esperada:</strong> <code>Ana</code>', difficulty: 'easy', starterCode: 'Persona p = new Persona("Ana", 25);', solution: 'System.out.println(p.nombre);', hint: 'Accede a atributos con objeto.atributo: p.nombre', validation: { requiredKeywords: ['.nombre'] } },
    { id: 65, lessonId: 16, title: 'Método de Instancia', description: '<strong>Resultado esperado:</strong> en la clase <code>Persona</code> añade el método público <code>void saludar()</code>, sin parámetros, que imprima <code>Hola, soy </code> seguido del atributo <code>nombre</code>. Para <code>nombre = "Ana"</code> debe imprimir <code>Hola, soy Ana</code>.', difficulty: 'medium', starterCode: 'public class Persona {\n    String nombre;\n}', solution: 'public void saludar() {\n    System.out.println("Hola, soy " + nombre);\n}', hint: 'Método de instancia: public void nombreMetodo() { }. Puede usar atributos directamente.', validation: { requiredKeywords: ['void', 'saludar'] } },
    { id: 66, lessonId: 16, title: 'Llamar Método', description: '<strong>Qué hacer:</strong> el objeto <code>p</code> ya está creado como <code>Persona("Ana", 25)</code>. Llama a su método <code>saludar()</code> con el punto (<code>p.saludar()</code>). Considera que <code>saludar()</code> ya existe en <code>Persona</code>.<br><strong>Salida esperada:</strong> <code>Hola, soy Ana</code>', difficulty: 'easy', starterCode: 'Persona p = new Persona("Ana", 25);', solution: 'p.saludar();', hint: 'Llama métodos con objeto.metodo(): p.saludar();', validation: { requiredKeywords: ['.saludar'] } },
    { id: 67, lessonId: 18, title: 'Encapsulamiento Private', description: '<strong>Resultado esperado:</strong> en la clase <code>Cuenta</code>, el atributo <code>saldo</code> de tipo <code>double</code> debe quedar declarado con el modificador <code>private</code>, para que no pueda usarse directamente desde fuera de la clase.', difficulty: 'medium', starterCode: 'public class Cuenta {\n    double saldo;\n}', solution: 'private double saldo;', hint: 'private oculta el atributo. Solo accesible dentro de la clase.', validation: { requiredKeywords: ['private'] } },
    { id: 68, lessonId: 18, title: 'Getter', description: '<strong>Resultado esperado:</strong> en la clase <code>Cuenta</code> añade el método público <code>getSaldo()</code>, sin parámetros, que devuelva con <code>return</code> el valor del atributo privado <code>saldo</code> (tipo <code>double</code>).', difficulty: 'medium', starterCode: 'public class Cuenta {\n    private double saldo;\n}', solution: 'public double getSaldo() {\n    return saldo;\n}', hint: 'Getter: public tipo getNombre() { return atributo; }', validation: { requiredKeywords: ['get', 'return'] } },
    { id: 69, lessonId: 18, title: 'Setter', description: '<strong>Resultado esperado:</strong> en la clase <code>Cuenta</code> añade el método público <code>void setSaldo(double saldo)</code> que use <code>this</code> para guardar el parámetro en el atributo privado <code>saldo</code>.', difficulty: 'medium', starterCode: 'public class Cuenta {\n    private double saldo;\n}', solution: 'public void setSaldo(double saldo) {\n    this.saldo = saldo;\n}', hint: 'Setter: public void setNombre(tipo param) { this.atributo = param; }', validation: { requiredKeywords: ['set', 'this'] } },
    { id: 70, lessonId: 18, title: 'Validación en Setter', description: '<strong>Resultado esperado:</strong> en la clase <code>Persona</code> añade el método público <code>void setEdad(int edad)</code>. Con un <code>if</code>, solo debe asignar <code>this.edad = edad</code> cuando el valor sea mayor o igual que 0; si es negativo, no cambia nada.', difficulty: 'hard', starterCode: 'public class Persona {\n    private int edad;\n}', solution: 'public void setEdad(int edad) {\n    if (edad >= 0) {\n        this.edad = edad;\n    }\n}', hint: 'Valida antes de asignar: if (condición) { this.atributo = valor; }', validation: { requiredKeywords: ['if', 'this'] } },
    { id: 71, lessonId: 19, title: 'Herencia Extends', description: '<strong>Resultado esperado:</strong> crea la clase pública <code>Estudiante</code> que herede de <code>Persona</code> con <code>extends</code> y que añada su propio atributo <code>carrera</code> de tipo <code>String</code>. No imprime nada.', difficulty: 'medium', starterCode: 'public class Persona {\n    String nombre;\n}', solution: 'public class Estudiante extends Persona {\n    String carrera;\n}', hint: 'Herencia: class Hija extends Padre { }. Estudiante hereda atributos de Persona.', validation: { requiredKeywords: ['extends'] } },
    { id: 72, lessonId: 19, title: 'Super Constructor', description: '<strong>Resultado esperado:</strong> en la clase <code>Estudiante</code> añade un constructor público <code>Estudiante(String nombre, String carrera)</code>. Su primera línea debe llamar a <code>super(nombre)</code> y luego debe asignar <code>this.carrera = carrera</code>. Considera que <code>Persona</code> ya tiene un constructor que recibe el nombre.', difficulty: 'hard', starterCode: 'public class Estudiante extends Persona {\n    String carrera;\n}', solution: 'public Estudiante(String nombre, String carrera) {\n    super(nombre);\n    this.carrera = carrera;\n}', hint: 'super() llama al constructor del padre. Debe ser la primera línea.', validation: { requiredKeywords: ['super'] } },
    { id: 73, lessonId: 19, title: 'Override Método', description: '<strong>Resultado esperado:</strong> en la clase <code>Persona</code> sobrescribe el método <code>toString()</code> con la anotación <code>@Override</code>. Debe devolver (con <code>return</code>, sin imprimir) el texto <code>"Persona: "</code> seguido del atributo <code>nombre</code>; para <code>"Ana"</code> devuelve <code>Persona: Ana</code>.', difficulty: 'medium', starterCode: 'public class Persona {\n    String nombre;\n}', solution: '@Override\npublic String toString() {\n    return "Persona: " + nombre;\n}', hint: '@Override indica que sobrescribes un método del padre o interfaz.', validation: { requiredKeywords: ['@Override', 'toString'] } },
    { id: 74, lessonId: 19, title: 'Polimorfismo', description: '<strong>Resultado esperado:</strong> una línea que cree con <code>new</code> un <code>Estudiante</code> con nombre <code>"Ana"</code> y carrera <code>"Ingeniería"</code>, y lo guarde en una variable <code>p</code> declarada con el tipo padre <code>Persona</code>. Considera que ambas clases ya existen. No imprime nada.', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: 'Persona p = new Estudiante("Ana", "Ingeniería");', hint: 'Polimorfismo: TipoPadre variable = new TipoHijo(); Permite flexibilidad.', validation: { requiredKeywords: ['Persona', 'Estudiante'] } },
    { id: 75, lessonId: 20, title: 'Clase Abstracta', description: '<strong>Resultado esperado:</strong> una clase pública <code>abstract</code> llamada <code>Animal</code> con un método abstracto público <code>void hacerSonido()</code>, sin cuerpo (termina en <code>;</code>). No imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'public abstract class Animal {\n    public abstract void hacerSonido();\n}', hint: 'abstract class no se puede instanciar. Métodos abstract no tienen cuerpo.', validation: { requiredKeywords: ['abstract'] } },
    { id: 76, lessonId: 20, title: 'Implementar Abstracto', description: '<strong>Resultado esperado:</strong> crea la clase pública <code>Perro</code> que herede de <code>Animal</code> con <code>extends</code> e implemente <code>public void hacerSonido()</code> con <code>@Override</code>. Ese método debe imprimir <code>Guau</code>; el programa por sí solo no imprime nada hasta que alguien lo llame.', difficulty: 'hard', starterCode: 'public abstract class Animal {\n    public abstract void hacerSonido();\n}', solution: 'public class Perro extends Animal {\n    @Override\n    public void hacerSonido() {\n        System.out.println("Guau");\n    }\n}', hint: 'Clases concretas deben implementar todos los métodos abstractos con @Override.', validation: { requiredKeywords: ['extends', '@Override'] } },
    { id: 77, lessonId: 21, title: 'Interfaz', description: '<strong>Resultado esperado:</strong> una interfaz pública llamada <code>Volador</code> con un único método <code>void volar();</code>, sin cuerpo. No imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'public interface Volador {\n    void volar();\n}', hint: 'interface define un contrato. Métodos son públicos y abstractos por defecto.', validation: { requiredKeywords: ['interface'] } },
    { id: 78, lessonId: 21, title: 'Implementar Interfaz', description: '<strong>Resultado esperado:</strong> crea la clase pública <code>Ave</code> que cumpla la interfaz <code>Volador</code> con <code>implements</code>. Debe implementar <code>public void volar()</code> con <code>@Override</code>, imprimiendo <code>Volando</code> al ser llamado.', difficulty: 'medium', starterCode: 'public interface Volador {\n    void volar();\n}', solution: 'public class Ave implements Volador {\n    @Override\n    public void volar() {\n        System.out.println("Volando");\n    }\n}', hint: 'implements indica que la clase cumple el contrato de la interfaz.', validation: { requiredKeywords: ['implements', '@Override'] } },
    { id: 79, lessonId: 21, title: 'Múltiples Interfaces', description: '<strong>Resultado esperado:</strong> crea la clase pública <code>Pato</code> que implemente a la vez las interfaces <code>Volador</code> y <code>Nadador</code> (<code>implements Volador, Nadador</code>), con los métodos públicos <code>volar()</code> y <code>nadar()</code>. Los cuerpos pueden estar vacíos. Considera que ambas interfaces ya existen con esos métodos.', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: 'public class Pato implements Volador, Nadador {\n    public void volar() { }\n    public void nadar() { }\n}', hint: 'Una clase puede implementar múltiples interfaces: implements I1, I2', validation: { requiredKeywords: ['implements'] } },
    { id: 80, lessonId: 21, title: 'Interfaz con Default', description: '<strong>Resultado esperado:</strong> dentro de la interfaz <code>Saludable</code> añade un método <code>default void despedir()</code> con cuerpo, que imprima <code>Adiós</code>. Deja intacto el método abstracto <code>saludar()</code>.', difficulty: 'hard', starterCode: 'public interface Saludable {\n    void saludar();\n}', solution: 'default void despedir() {\n    System.out.println("Adiós");\n}', hint: 'Métodos default (Java 8+) tienen implementación en la interfaz.', validation: { requiredKeywords: ['default'] } },

    // IDs 81-100: POO Avanzado
    { id: 81, lessonId: 26, title: 'Atributo Static', description: '<strong>Qué hacer:</strong> Dentro de la clase <code>Contador</code> (que ya tiene el atributo <code>valor</code>), agrega un atributo <code>int</code> llamado <code>total</code> con valor inicial 0 que sea compartido por todos los objetos de la clase (la palabra clave para eso es <code>static</code>).<br><strong>Resultado esperado:</strong> la clase <code>Contador</code> declara un atributo estático <code>total</code> de tipo <code>int</code> con valor inicial 0. No imprime nada.', difficulty: 'medium', starterCode: 'public class Contador {\n    int valor;\n}', solution: 'static int total = 0;', hint: 'static pertenece a la clase, no a instancias. Se comparte entre todos los objetos.', validation: { requiredKeywords: ['static'] } },
    { id: 82, lessonId: 26, title: 'Método Static', description: '<strong>Qué hacer:</strong> Dentro de la clase <code>Utilidades</code>, escribe un método de clase <code>public static int sumar(int a, int b)</code> que devuelva la suma de ambos números.<br><strong>Resultado esperado:</strong> el método <code>static</code> <code>sumar</code> existe y, por ejemplo, <code>Utilidades.sumar(2, 3)</code> devolvería 5. No imprime nada.', difficulty: 'medium', starterCode: 'public class Utilidades {\n}', solution: 'public static int sumar(int a, int b) {\n    return a + b;\n}', hint: 'Métodos static se llaman con NombreClase.metodo(), no necesitan instancia.', validation: { requiredKeywords: ['static'] } },
    { id: 83, lessonId: 26, title: 'Constante Static Final', description: '<strong>Qué hacer:</strong> Declara una constante de clase llamada <code>PI</code> de tipo <code>double</code> con valor <code>3.14159</code>, usando <code>public static final</code>.<br><strong>Resultado esperado:</strong> existe la constante <code>PI</code> (<code>public static final double</code>) igual a 3.14159. No imprime nada.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'public static final double PI = 3.14159;', hint: 'static final define constantes de clase. Por convención en MAYÚSCULAS.', validation: { requiredKeywords: ['static', 'final'] } },
    { id: 84, lessonId: 26, title: 'Bloque Static', description: '<strong>Qué hacer:</strong> Dentro de la clase <code>Config</code> (que ya declara <code>static String url;</code>), escribe un bloque <code>static { ... }</code> que asigne a <code>url</code> el texto <code>"http://localhost"</code>.<br><strong>Resultado esperado:</strong> al cargarse la clase, <code>Config.url</code> vale <code>"http://localhost"</code>. No imprime nada.', difficulty: 'hard', starterCode: 'public class Config {\n    static String url;\n}', solution: 'static {\n    url = "http://localhost";\n}', hint: 'Bloque static { } se ejecuta una vez al cargar la clase.', validation: { requiredKeywords: ['static'] } },
    { id: 85, lessonId: 24, title: 'Clase Interna', description: '<strong>Qué hacer:</strong> Dentro de la clase <code>Externa</code>, declara una clase interna llamada <code>Interna</code> que tenga un método <code>void metodo()</code> con el cuerpo vacío.<br><strong>Resultado esperado:</strong> <code>Externa</code> contiene la clase <code>Interna</code> con el método <code>metodo()</code>. No imprime nada.', difficulty: 'medium', starterCode: 'public class Externa {\n}', solution: 'class Interna {\n    void metodo() { }\n}', hint: 'Clase interna se define dentro de otra clase. Tiene acceso a miembros de la externa.', validation: { requiredKeywords: ['class'] } },
    { id: 86, lessonId: 24, title: 'Clase Anónima', description: '<strong>Qué hacer:</strong> Completa la línea <code>Runnable r = </code> con una clase anónima: <code>new Runnable() { ... };</code>. Dentro, sobrescribe <code>run()</code> con <code>@Override</code> y haz que imprima <code>Hola</code> con <code>System.out.println</code>.<br><strong>Resultado esperado:</strong> la variable <code>r</code> guarda el objeto anónimo; al ejecutar <code>r.run()</code> se imprimiría <code>Hola</code>. Por sí sola la declaración no imprime nada.', difficulty: 'hard', starterCode: 'Runnable r = ', solution: 'new Runnable() {\n    @Override\n    public void run() {\n        System.out.println("Hola");\n    }\n};', hint: 'Clase anónima: new Interfaz() { métodos }; Útil para implementaciones únicas.', validation: { requiredKeywords: ['new', '@Override'] } },
    { id: 87, lessonId: 23, title: 'Enum Simple', description: '<strong>Qué hacer:</strong> Declara un enum público llamado <code>Dia</code> con tres valores, en este orden: <code>LUNES</code>, <code>MARTES</code> y <code>MIERCOLES</code>.<br><strong>Resultado esperado:</strong> existe <code>enum Dia</code> con esas tres constantes. No imprime nada.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'public enum Dia {\n    LUNES, MARTES, MIERCOLES\n}', hint: 'enum define un conjunto fijo de constantes: enum Nombre { VALOR1, VALOR2 }', validation: { requiredKeywords: ['enum'] } },
    { id: 88, lessonId: 23, title: 'Enum con Constructor', description: '<strong>Qué hacer:</strong> Declara un enum público <code>Talla</code> con los valores <code>S(1)</code>, <code>M(2)</code> y <code>L(3)</code>. Agrega un atributo <code>private int numero</code> y un constructor <code>Talla(int numero)</code> que lo asigne con <code>this.numero = numero</code>.<br><strong>Resultado esperado:</strong> el enum <code>Talla</code> compila, con el atributo <code>private</code> y su constructor. No imprime nada.', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: 'public enum Talla {\n    S(1), M(2), L(3);\n    private int numero;\n    Talla(int numero) {\n        this.numero = numero;\n    }\n}', hint: 'Enums pueden tener constructores y atributos. Constructor es privado.', validation: { requiredKeywords: ['enum', 'private'] } },
    { id: 89, lessonId: 28, title: 'Equals Override', description: '<strong>Qué hacer:</strong> En la clase <code>Persona</code> (que ya tiene <code>String nombre</code>), sobrescribe <code>public boolean equals(Object obj)</code> con <code>@Override</code>. Usa <code>instanceof</code> para comprobar que <code>obj</code> es una <code>Persona</code> y, si lo es, devuelve si los <code>nombre</code> son iguales; en caso contrario devuelve <code>false</code>.<br><strong>Resultado esperado:</strong> dos <code>Persona</code> con el mismo <code>nombre</code> serían iguales según <code>equals</code>. No imprime nada.', difficulty: 'hard', starterCode: 'public class Persona {\n    String nombre;\n}', solution: '@Override\npublic boolean equals(Object obj) {\n    if (obj instanceof Persona) {\n        return nombre.equals(((Persona) obj).nombre);\n    }\n    return false;\n}', hint: 'equals() compara contenido. Usa instanceof y casting.', validation: { requiredKeywords: ['@Override', 'equals', 'instanceof'] } },
    { id: 90, lessonId: 28, title: 'HashCode Override', description: '<strong>Qué hacer:</strong> En la clase <code>Persona</code> (que ya tiene <code>String nombre</code>), sobrescribe con <code>@Override</code> el método <code>public int hashCode()</code> para que devuelva <code>nombre.hashCode()</code>.<br><strong>Resultado esperado:</strong> el método <code>hashCode</code> existe y personas con el mismo <code>nombre</code> dan el mismo número. No imprime nada.', difficulty: 'hard', starterCode: 'public class Persona {\n    String nombre;\n}', solution: '@Override\npublic int hashCode() {\n    return nombre.hashCode();\n}', hint: 'Si sobrescribes equals(), también debes sobrescribir hashCode().', validation: { requiredKeywords: ['@Override', 'hashCode'] } },
    { id: 91, lessonId: 30, title: 'CompareTo', description: '<strong>Qué hacer:</strong> En la clase <code>Persona</code> (que ya implementa <code>Comparable&lt;Persona&gt;</code> y tiene <code>int edad</code>), escribe con <code>@Override</code> el método <code>public int compareTo(Persona otra)</code> que compare las edades con <code>Integer.compare(this.edad, otra.edad)</code>.<br><strong>Resultado esperado:</strong> <code>compareTo</code> devuelve un número negativo, 0 o positivo según la edad. No imprime nada.', difficulty: 'hard', starterCode: 'public class Persona implements Comparable<Persona> {\n    int edad;\n}', solution: '@Override\npublic int compareTo(Persona otra) {\n    return Integer.compare(this.edad, otra.edad);\n}', hint: 'compareTo() retorna negativo, 0, o positivo según el orden.', validation: { requiredKeywords: ['@Override', 'compareTo'] } },
    { id: 92, lessonId: 27, title: 'Genérico Simple', description: '<strong>Qué hacer:</strong> Declara una clase pública genérica <code>Caja&lt;T&gt;</code> con un atributo privado <code>T contenido</code> y un método <code>public void guardar(T item)</code> que asigne <code>item</code> a <code>contenido</code>.<br><strong>Resultado esperado:</strong> la clase <code>Caja&lt;T&gt;</code> compila y <code>new Caja&lt;String&gt;().guardar("hola")</code> sería válido. No imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'public class Caja<T> {\n    private T contenido;\n    public void guardar(T item) {\n        contenido = item;\n    }\n}', hint: 'Genéricos usan <T> como tipo parámetro. T se reemplaza al usar la clase.', validation: { requiredKeywords: ['<T>'] } },
    { id: 93, lessonId: 27, title: 'Método Genérico', description: '<strong>Qué hacer:</strong> Escribe un método genérico <code>public static &lt;T&gt; void imprimir(T elemento)</code> que muestre el <code>elemento</code> con <code>System.out.println</code>.<br><strong>Resultado esperado:</strong> <code>imprimir("Hola")</code> mostraría <code>Hola</code> e <code>imprimir(42)</code> mostraría <code>42</code>.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'public static <T> void imprimir(T elemento) {\n    System.out.println(elemento);\n}', hint: 'Método genérico: <T> antes del tipo de retorno. Ejemplo: <T> void metodo(T param)', validation: { requiredKeywords: ['<T>'] } },
    { id: 94, lessonId: 27, title: 'Bounded Type', description: '<strong>Qué hacer:</strong> Declara una clase pública <code>Comparador&lt;T extends Comparable&lt;T&gt;&gt;</code> con un método <code>public T mayor(T a, T b)</code> que devuelva el mayor de los dos usando <code>a.compareTo(b)</code>.<br><strong>Resultado esperado:</strong> <code>new Comparador&lt;Integer&gt;().mayor(3, 8)</code> devolvería 8. No imprime nada.', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: 'public class Comparador<T extends Comparable<T>> {\n    public T mayor(T a, T b) {\n        return a.compareTo(b) > 0 ? a : b;\n    }\n}', hint: '<T extends Tipo> limita T a subtipos de Tipo.', validation: { requiredKeywords: ['<T extends'] } },
    { id: 95, lessonId: 27, title: 'Wildcard ?', description: '<strong>Qué hacer:</strong> Escribe un método <code>public void imprimir(List&lt;?&gt; lista)</code> que recorra la lista con un <code>for</code> sobre <code>Object obj</code> e imprima cada elemento con <code>System.out.println</code>.<br><strong>Resultado esperado:</strong> con la lista <code>["a", "b"]</code> se imprimiría <code>a</code> y luego <code>b</code>, cada uno en su línea. El método acepta una lista de cualquier tipo.', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: 'public void imprimir(List<?> lista) {\n    for (Object obj : lista) {\n        System.out.println(obj);\n    }\n}', hint: '? (wildcard) acepta cualquier tipo. List<?> acepta List de cualquier cosa.', validation: { requiredKeywords: ['?'] } },
    { id: 96, lessonId: 23, title: 'Record Simple', description: '<strong>Qué hacer:</strong> Declara un record público llamado <code>Punto</code> con dos componentes enteros: <code>int x</code> e <code>int y</code>. El cuerpo puede quedar vacío.<br><strong>Resultado esperado:</strong> existe <code>record Punto(int x, int y)</code>; <code>new Punto(1, 2).x()</code> daría 1. No imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'public record Punto(int x, int y) { }', hint: 'record (Java 14+) es una clase inmutable con constructor, getters, equals, hashCode y toString automáticos.', validation: { requiredKeywords: ['record'] } },
    { id: 97, lessonId: 23, title: 'Sealed Class', description: '<strong>Qué hacer:</strong> Declara una clase pública sellada llamada <code>Forma</code> usando <code>sealed</code> y <code>permits</code>, de modo que solo puedan heredar de ella <code>Circulo</code> y <code>Cuadrado</code>. El cuerpo puede quedar vacío.<br><strong>Resultado esperado:</strong> una clase pública <code>Forma</code>, sellada, que permite solo a <code>Circulo</code> y <code>Cuadrado</code> como subclases (las subclases se definen aparte). No imprime nada.', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: 'public sealed class Forma permits Circulo, Cuadrado { }', hint: 'sealed (Java 17+) restringe qué clases pueden heredar. Usa permits.', validation: { requiredKeywords: ['sealed', 'permits'] } },
    { id: 98, lessonId: 19, title: 'Pattern Matching', description: '<strong>Qué hacer:</strong> la variable <code>obj</code> ya vale <code>"Hola"</code> (declarada como <code>Object</code>). Con <code>instanceof</code> y pattern matching, escribe un <code>if (obj instanceof String s)</code> y dentro imprime <code>s.toUpperCase()</code>.<br><strong>Salida esperada:</strong> <code>HOLA</code>', difficulty: 'medium', starterCode: 'Object obj = "Hola";', solution: 'if (obj instanceof String s) {\n    System.out.println(s.toUpperCase());\n}', hint: 'Pattern matching (Java 16+): instanceof Tipo variable declara la variable automáticamente.', validation: { requiredKeywords: ['instanceof'] } },
    { id: 99, lessonId: 13, title: 'Text Blocks', description: '<strong>Qué hacer:</strong> Declara una variable String llamada <code>json</code> usando un text block (tres comillas dobles <code>"""</code>) que contenga tres líneas: una llave de apertura, la línea <code>"nombre": "Ana"</code> y una llave de cierre.<br><strong>Resultado esperado:</strong> <code>json</code> guarda un texto multilínea con ese contenido. No imprime nada.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'String json = """\n    {\n        "nombre": "Ana"\n    }\n    """;', hint: 'Text blocks (Java 15+): """ texto multilínea """ preserva formato.', validation: { requiredKeywords: ['"""'] } },
    { id: 100, lessonId: 8, title: 'Switch Expression Yield', description: '<strong>Qué hacer:</strong> La variable <code>dia</code> ya vale 3. Declara <code>String tipo</code> con una switch expression con flechas: <code>case 1, 7</code> da <code>"Fin de semana"</code>; <code>case 2, 3, 4, 5, 6</code> abre un bloque que imprime <code>Día laboral</code> y devuelve <code>"Laboral"</code> con <code>yield</code>; <code>default</code> da <code>"Desconocido"</code>.<br><strong>Salida esperada:</strong> <code>Día laboral</code> (con <code>dia</code> igual a 3); <code>tipo</code> queda con el valor <code>"Laboral"</code>.', difficulty: 'hard', starterCode: 'int dia = 3;', solution: 'String tipo = switch (dia) {\n    case 1, 7 -> "Fin de semana";\n    case 2, 3, 4, 5, 6 -> {\n        System.out.println("Día laboral");\n        yield "Laboral";\n    }\n    default -> "Desconocido";\n};', hint: 'yield retorna un valor desde un bloque en switch expression.', validation: { requiredKeywords: ['switch', 'yield'] } },

    // IDs 101-120: Colecciones
    { id: 101, lessonId: 27, title: 'ArrayList Crear', description: '<strong>Qué hacer:</strong> Declara una variable <code>lista</code> de tipo <code>ArrayList&lt;String&gt;</code> y asígnale una lista nueva vacía con <code>new ArrayList&lt;&gt;()</code>. El <code>import</code> ya está escrito.<br><strong>Resultado esperado:</strong> <code>lista</code> existe y está vacía. No imprime nada.', difficulty: 'easy', starterCode: 'import java.util.ArrayList;', solution: 'ArrayList<String> lista = new ArrayList<>();', hint: 'ArrayList<Tipo> nombre = new ArrayList<>(); Es una lista dinámica.', validation: { requiredKeywords: ['ArrayList', 'new'] } },
    { id: 102, lessonId: 27, title: 'ArrayList Add', description: '<strong>Qué hacer:</strong> Considera que <code>lista</code> ya es un <code>ArrayList&lt;String&gt;</code> vacío. Agrega a la lista los textos <code>"Hola"</code> y <code>"Mundo"</code> con <code>add</code>.<br><strong>Resultado esperado:</strong> <code>lista</code> queda con dos elementos: <code>Hola</code> y <code>Mundo</code>. No imprime nada.', difficulty: 'easy', starterCode: 'ArrayList<String> lista = new ArrayList<>();', solution: 'lista.add("Hola");\nlista.add("Mundo");', hint: 'Usa .add(elemento) para agregar al final de la lista.', validation: { requiredKeywords: ['add'] } },
    { id: 103, lessonId: 27, title: 'ArrayList Get', description: '<strong>Qué hacer:</strong> Considera que <code>lista</code> ya contiene <code>"Hola"</code>. Guarda en una variable <code>String primero</code> el elemento de la posición 0 usando <code>get</code>.<br><strong>Resultado esperado:</strong> <code>primero</code> vale <code>"Hola"</code>. No imprime nada.', difficulty: 'easy', starterCode: 'ArrayList<String> lista = new ArrayList<>();\nlista.add("Hola");', solution: 'String primero = lista.get(0);', hint: 'Usa .get(índice) para obtener un elemento. Índices empiezan en 0.', validation: { requiredKeywords: ['get'] } },
    { id: 104, lessonId: 27, title: 'ArrayList Remove', description: '<strong>Qué hacer:</strong> Considera que <code>lista</code> ya contiene <code>"A"</code> y <code>"B"</code>. Elimina el primer elemento con <code>remove(0)</code>.<br><strong>Resultado esperado:</strong> la lista queda solo con <code>"B"</code>. No imprime nada.', difficulty: 'medium', starterCode: 'ArrayList<String> lista = new ArrayList<>();\nlista.add("A");\nlista.add("B");', solution: 'lista.remove(0);', hint: 'remove(índice) elimina por posición. remove(objeto) elimina por valor.', validation: { requiredKeywords: ['remove'] } },
    { id: 105, lessonId: 27, title: 'ArrayList Size', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya es un <code>ArrayList&lt;Integer&gt;</code>. Guarda su cantidad de elementos en una variable <code>int tamaño</code> usando <code>size()</code>.<br><strong>Resultado esperado:</strong> <code>tamaño</code> contiene la cantidad de elementos (0 si la lista está vacía). No imprime nada.', difficulty: 'easy', starterCode: 'ArrayList<Integer> nums = new ArrayList<>();', solution: 'int tamaño = nums.size();', hint: 'Usa .size() para obtener la cantidad de elementos.', validation: { requiredKeywords: ['size'] } },
    { id: 106, lessonId: 27, title: 'ArrayList Iterar', description: '<strong>Qué hacer:</strong> Considera que <code>lista</code> ya es un <code>ArrayList&lt;String&gt;</code>. Recórrela con un bucle <code>for</code> de tipo for-each (<code>for (String item : lista)</code>) e imprime cada <code>item</code> con <code>System.out.println</code>.<br><strong>Resultado esperado:</strong> si la lista tuviera <code>"A"</code> y <code>"B"</code> se verían <code>A</code> y <code>B</code> en líneas separadas (con la lista vacía no imprime nada).', difficulty: 'medium', starterCode: 'ArrayList<String> lista = new ArrayList<>();', solution: 'for (String item : lista) {\n    System.out.println(item);\n}', hint: 'for (Tipo variable : lista) { } recorre todos los elementos.', validation: { requiredKeywords: ['for', ':'] } },
    { id: 107, lessonId: 28, title: 'HashSet Crear', description: '<strong>Qué hacer:</strong> Declara una variable <code>set</code> de tipo <code>HashSet&lt;String&gt;</code> y asígnale un <code>HashSet</code> nuevo vacío con <code>new HashSet&lt;&gt;()</code>. El <code>import</code> ya está escrito.<br><strong>Resultado esperado:</strong> <code>set</code> existe y está vacío. No imprime nada.', difficulty: 'easy', starterCode: 'import java.util.HashSet;', solution: 'HashSet<String> set = new HashSet<>();', hint: 'HashSet no permite duplicados y no garantiza orden.', validation: { requiredKeywords: ['HashSet'] } },
    { id: 108, lessonId: 28, title: 'HashSet Add Duplicado', description: '<strong>Qué hacer:</strong> Considera que <code>set</code> ya es un <code>HashSet&lt;String&gt;</code> vacío. Agrega <code>"Hola"</code> dos veces con <code>add</code> y luego imprime <code>set.size()</code> con <code>System.out.println</code>.<br><strong>Resultado esperado:</strong> <code>1</code> (el segundo <code>add</code> se ignora por estar repetido).', difficulty: 'medium', starterCode: 'HashSet<String> set = new HashSet<>();', solution: 'set.add("Hola");\nset.add("Hola");\nSystem.out.println(set.size());', hint: 'add() retorna false si el elemento ya existe. size() será 1.', validation: { requiredKeywords: ['add', 'size'] } },
    { id: 109, lessonId: 28, title: 'HashSet Contains', description: '<strong>Qué hacer:</strong> Considera que <code>set</code> ya contiene <code>"Java"</code>. Guarda en una variable <code>boolean existe</code> el resultado de <code>set.contains("Java")</code>.<br><strong>Resultado esperado:</strong> <code>existe</code> vale <code>true</code>. No imprime nada.', difficulty: 'easy', starterCode: 'HashSet<String> set = new HashSet<>();\nset.add("Java");', solution: 'boolean existe = set.contains("Java");', hint: 'contains(elemento) retorna true si el elemento está en el set.', validation: { requiredKeywords: ['contains'] } },
    { id: 110, lessonId: 29, title: 'HashMap Crear', description: '<strong>Qué hacer:</strong> Declara una variable <code>mapa</code> de tipo <code>HashMap&lt;String, Integer&gt;</code> y asígnale un <code>HashMap</code> nuevo vacío con <code>new HashMap&lt;&gt;()</code>. El <code>import</code> ya está escrito.<br><strong>Resultado esperado:</strong> <code>mapa</code> existe y está vacío. No imprime nada.', difficulty: 'easy', starterCode: 'import java.util.HashMap;', solution: 'HashMap<String, Integer> mapa = new HashMap<>();', hint: 'HashMap<TipoClave, TipoValor> almacena pares clave-valor.', validation: { requiredKeywords: ['HashMap'] } },
    { id: 111, lessonId: 29, title: 'HashMap Put', description: '<strong>Qué hacer:</strong> Considera que <code>edades</code> ya es un <code>HashMap&lt;String, Integer&gt;</code> vacío. Agrega con <code>put</code> los pares <code>"Ana"</code> con 25 y <code>"Luis"</code> con 30.<br><strong>Resultado esperado:</strong> <code>edades</code> queda con dos pares: Ana=25 y Luis=30. No imprime nada.', difficulty: 'easy', starterCode: 'HashMap<String, Integer> edades = new HashMap<>();', solution: 'edades.put("Ana", 25);\nedades.put("Luis", 30);', hint: 'put(clave, valor) agrega o actualiza un par.', validation: { requiredKeywords: ['put'] } },
    { id: 112, lessonId: 29, title: 'HashMap Get', description: '<strong>Qué hacer:</strong> Considera que <code>edades</code> ya contiene <code>"Ana"</code> con valor 25. Guarda en una variable <code>int edad</code> el valor asociado a <code>"Ana"</code> usando <code>get</code>.<br><strong>Resultado esperado:</strong> <code>edad</code> vale <code>25</code>. No imprime nada.', difficulty: 'easy', starterCode: 'HashMap<String, Integer> edades = new HashMap<>();\nedades.put("Ana", 25);', solution: 'int edad = edades.get("Ana");', hint: 'get(clave) retorna el valor asociado. Retorna null si no existe.', validation: { requiredKeywords: ['get'] } },
    { id: 113, lessonId: 29, title: 'HashMap ContainsKey', description: '<strong>Qué hacer:</strong> Considera que <code>mapa</code> ya es un <code>HashMap&lt;String, Integer&gt;</code>. Con un <code>if</code> y <code>containsKey</code>, comprueba si existe la clave <code>"Ana"</code>; si existe, imprime <code>Existe</code>.<br><strong>Resultado esperado:</strong> si el mapa tiene la clave <code>"Ana"</code> se imprime <code>Existe</code>; si el mapa está vacío no imprime nada.', difficulty: 'medium', starterCode: 'HashMap<String, Integer> mapa = new HashMap<>();', solution: 'if (mapa.containsKey("Ana")) {\n    System.out.println("Existe");\n}', hint: 'containsKey(clave) verifica si la clave existe antes de usar get().', validation: { requiredKeywords: ['containsKey'] } },
    { id: 114, lessonId: 29, title: 'HashMap Iterar', description: '<strong>Qué hacer:</strong> Considera que <code>edades</code> ya es un <code>HashMap&lt;String, Integer&gt;</code>. Recórrelo con un <code>for</code> sobre <code>edades.entrySet()</code> usando <code>Map.Entry&lt;String, Integer&gt; entry</code>, e imprime cada par con <code>getKey()</code> y <code>getValue()</code>.<br><strong>Resultado esperado:</strong> con el par Ana=25 se imprimiría <code>Ana: 25</code> (una línea por par).', difficulty: 'hard', starterCode: 'HashMap<String, Integer> edades = new HashMap<>();', solution: 'for (Map.Entry<String, Integer> entry : edades.entrySet()) {\n    System.out.println(entry.getKey() + ": " + entry.getValue());\n}', hint: 'entrySet() retorna pares. Usa getKey() y getValue().', validation: { requiredKeywords: ['entrySet', 'getKey', 'getValue'] } },
    { id: 115, lessonId: 27, title: 'LinkedList Crear', description: '<strong>Qué hacer:</strong> Declara una variable <code>lista</code> de tipo <code>LinkedList&lt;String&gt;</code> y asígnale una lista nueva vacía con <code>new LinkedList&lt;&gt;()</code>. El <code>import</code> ya está escrito.<br><strong>Resultado esperado:</strong> <code>lista</code> existe y está vacía. No imprime nada.', difficulty: 'easy', starterCode: 'import java.util.LinkedList;', solution: 'LinkedList<String> lista = new LinkedList<>();', hint: 'LinkedList es eficiente para insertar/eliminar en medio.', validation: { requiredKeywords: ['LinkedList'] } },
    { id: 116, lessonId: 27, title: 'LinkedList AddFirst', description: '<strong>Qué hacer:</strong> Considera que <code>lista</code> ya es un <code>LinkedList&lt;String&gt;</code> vacío. Agrega <code>"Primero"</code> al inicio con <code>addFirst</code> y <code>"Último"</code> al final con <code>addLast</code>.<br><strong>Resultado esperado:</strong> la lista queda como <code>[Primero, Último]</code>. No imprime nada.', difficulty: 'medium', starterCode: 'LinkedList<String> lista = new LinkedList<>();', solution: 'lista.addFirst("Primero");\nlista.addLast("Último");', hint: 'addFirst() y addLast() agregan en extremos específicos.', validation: { requiredKeywords: ['addFirst'] } },
    { id: 117, lessonId: 28, title: 'TreeSet Ordenado', description: '<strong>Qué hacer:</strong> Declara <code>set</code> como <code>TreeSet&lt;Integer&gt;</code> con <code>new TreeSet&lt;&gt;()</code> y agrega en este orden los números 5, 1 y 3 con <code>add</code>. El <code>import</code> ya está escrito.<br><strong>Resultado esperado:</strong> el set queda ordenado automáticamente como <code>[1, 3, 5]</code>. No imprime nada.', difficulty: 'medium', starterCode: 'import java.util.TreeSet;', solution: 'TreeSet<Integer> set = new TreeSet<>();\nset.add(5);\nset.add(1);\nset.add(3);', hint: 'TreeSet mantiene elementos ordenados automáticamente.', validation: { requiredKeywords: ['TreeSet'] } },
    { id: 118, lessonId: 30, title: 'Collections Sort', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya es un <code>ArrayList&lt;Integer&gt;</code> con números. Ordénala de menor a mayor con <code>Collections.sort(nums)</code>.<br><strong>Resultado esperado:</strong> <code>nums</code> queda ordenada de menor a mayor (por ejemplo [3, 1, 2] pasa a [1, 2, 3]). No imprime nada.', difficulty: 'medium', starterCode: 'import java.util.*;\nArrayList<Integer> nums = new ArrayList<>();', solution: 'Collections.sort(nums);', hint: 'Collections.sort(lista) ordena in-place.', validation: { requiredKeywords: ['Collections.sort'] } },
    { id: 119, lessonId: 30, title: 'Collections Reverse', description: '<strong>Qué hacer:</strong> Considera que <code>lista</code> ya es un <code>ArrayList&lt;String&gt;</code> con elementos. Invierte su orden con <code>Collections.reverse(lista)</code>.<br><strong>Resultado esperado:</strong> el orden queda al revés (por ejemplo [A, B, C] pasa a [C, B, A]). No imprime nada.', difficulty: 'easy', starterCode: 'import java.util.*;\nArrayList<String> lista = new ArrayList<>();', solution: 'Collections.reverse(lista);', hint: 'Collections.reverse(lista) invierte el orden.', validation: { requiredKeywords: ['Collections.reverse'] } },
    { id: 120, lessonId: 30, title: 'Collections Max', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya es un <code>ArrayList&lt;Integer&gt;</code> con al menos un elemento. Guarda en una variable <code>int max</code> el mayor con <code>Collections.max(nums)</code>.<br><strong>Resultado esperado:</strong> <code>max</code> contiene el mayor número de la lista (con [4, 9, 2] sería 9). No imprime nada.', difficulty: 'medium', starterCode: 'import java.util.*;\nArrayList<Integer> nums = new ArrayList<>();', solution: 'int max = Collections.max(nums);', hint: 'Collections.max(colección) retorna el elemento mayor.', validation: { requiredKeywords: ['Collections.max'] } },

    // IDs 121-168: AVANZADO (Excepciones, Functional, Stream, I/O)
    // IDs 121-140: Excepciones y manejo de errores
    { id: 121, lessonId: 31, title: 'Try-Catch Básico', description: '<strong>Qué hacer:</strong> Envuelve la línea <code>int x = Integer.parseInt("abc");</code> en un bloque <code>try</code> y captura la <code>NumberFormatException</code> con un <code>catch</code>. Dentro del <code>catch</code>, imprime el mensaje indicado.<br><strong>Salida esperada:</strong> <code>Error de formato</code>', difficulty: 'easy', starterCode: 'int x = Integer.parseInt("abc");', solution: 'try {\n    int x = Integer.parseInt("abc");\n} catch (NumberFormatException e) {\n    System.out.println("Error de formato");\n}', hint: 'try { código } catch (TipoExcepción e) { manejo }', validation: { requiredKeywords: ['try', 'catch'] } },
    { id: 122, lessonId: 31, title: 'Múltiples Catch', description: '<strong>Qué hacer:</strong> Escribe un bloque <code>try</code> seguido de dos bloques <code>catch</code>: el primero para <code>NullPointerException</code>, que imprime <code>Null</code>, y el segundo para <code>ArrayIndexOutOfBoundsException</code>, que imprime <code>Índice</code>. Dentro del <code>try</code> puedes dejar solo un comentario.<br><strong>Resultado esperado:</strong> el código compila con los dos <code>catch</code> en ese orden. Como el <code>try</code> no lanza ninguna excepción, no se imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'try {\n    // código\n} catch (NullPointerException e) {\n    System.out.println("Null");\n} catch (ArrayIndexOutOfBoundsException e) {\n    System.out.println("Índice");\n}', hint: 'Puedes tener múltiples bloques catch para diferentes excepciones.', validation: { requiredKeywords: ['try', 'catch'] } },
    { id: 123, lessonId: 31, title: 'Finally', description: '<strong>Qué hacer:</strong> Escribe un <code>try</code> con un <code>catch (Exception e)</code> y un bloque <code>finally</code> que imprima el texto indicado. El <code>try</code> puede quedar con un comentario: <code>finally</code> se ejecuta igual.<br><strong>Salida esperada:</strong> <code>Siempre se ejecuta</code>', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'try {\n    // código\n} catch (Exception e) {\n    // manejo\n} finally {\n    System.out.println("Siempre se ejecuta");\n}', hint: 'finally se ejecuta siempre, haya o no excepción.', validation: { requiredKeywords: ['finally'] } },
    { id: 124, lessonId: 31, title: 'Throw Exception', description: '<strong>Qué hacer:</strong> Completa el cuerpo del método <code>validar(int edad)</code>: si <code>edad</code> es menor que 0, lanza con <code>throw new</code> una <code>IllegalArgumentException</code> cuyo mensaje sea <code>Edad negativa</code>.<br><strong>Resultado esperado:</strong> <code>validar(-1)</code> lanza <code>IllegalArgumentException: Edad negativa</code> y <code>validar(20)</code> no hace nada. El método no imprime nada.', difficulty: 'medium', starterCode: 'public void validar(int edad) {', solution: 'if (edad < 0) {\n    throw new IllegalArgumentException("Edad negativa");\n}', hint: 'throw new TipoExcepción("mensaje") lanza una excepción.', validation: { requiredKeywords: ['throw', 'new'] } },
    { id: 125, lessonId: 31, title: 'Throws en Firma', description: '<strong>Qué hacer:</strong> Declara un método <code>public void leerArchivo()</code> sin parámetros cuya firma indique con <code>throws</code> que puede lanzar <code>IOException</code>. El cuerpo puede ser solo un comentario.<br><strong>Resultado esperado:</strong> existe el método <code>public void leerArchivo() throws IOException</code>. No imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'public void leerArchivo() throws IOException {\n    // código que puede lanzar IOException\n}', hint: 'throws en la firma indica que el método puede lanzar esa excepción.', validation: { requiredKeywords: ['throws'] } },
    { id: 126, lessonId: 32, title: 'Excepción Personalizada', description: '<strong>Qué hacer:</strong> Crea la clase pública <code>MiExcepcion</code> que extienda <code>Exception</code>. Agrega un constructor que reciba un <code>String mensaje</code> y lo pase a la clase padre con <code>super(mensaje)</code>.<br><strong>Resultado esperado:</strong> la clase <code>MiExcepcion</code> existe, hereda de <code>Exception</code> y se puede crear con <code>new MiExcepcion("texto")</code>. No imprime nada.', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: 'public class MiExcepcion extends Exception {\n    public MiExcepcion(String mensaje) {\n        super(mensaje);\n    }\n}', hint: 'Extiende Exception para crear excepciones personalizadas.', validation: { requiredKeywords: ['extends', 'Exception'] } },
    { id: 127, lessonId: 32, title: 'RuntimeException', description: '<strong>Qué hacer:</strong> Crea la clase pública <code>ErrorNegocio</code> que extienda <code>RuntimeException</code>, con un constructor que reciba un <code>String msg</code> y lo pase a <code>super(msg)</code>.<br><strong>Resultado esperado:</strong> la clase <code>ErrorNegocio</code> existe y, al ser no verificada, se puede lanzar sin declarar <code>throws</code>. No imprime nada.', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'public class ErrorNegocio extends RuntimeException {\n    public ErrorNegocio(String msg) {\n        super(msg);\n    }\n}', hint: 'RuntimeException no necesita ser declarada con throws.', validation: { requiredKeywords: ['RuntimeException'] } },
    { id: 128, lessonId: 33, title: 'Try-With-Resources', description: '<strong>Qué hacer:</strong> Con <code>import java.io.*;</code> ya incluido, abre <code>file.txt</code> con <code>try-with-resources</code>: declara en el paréntesis del <code>try</code> un <code>BufferedReader br = new BufferedReader(new FileReader("file.txt"))</code>. Dentro, guarda <code>br.readLine()</code> en un <code>String linea</code>. Agrega un <code>catch (IOException e)</code> que llame a <code>e.printStackTrace()</code>.<br><strong>Resultado esperado:</strong> no imprime nada por la salida normal. Si <code>file.txt</code> no existe, <code>printStackTrace()</code> muestra el error en la consola de errores.', difficulty: 'hard', starterCode: 'import java.io.*;', solution: 'try (BufferedReader br = new BufferedReader(new FileReader("file.txt"))) {\n    String linea = br.readLine();\n} catch (IOException e) {\n    e.printStackTrace();\n}', hint: 'try (recurso) { } cierra automáticamente recursos AutoCloseable.', validation: { requiredKeywords: ['try'] } },
    { id: 129, lessonId: 31, title: 'Multi-Catch', description: '<strong>Qué hacer:</strong> Escribe un <code>try</code> con un único <code>catch</code> que atrape <code>IOException</code> y <code>SQLException</code> a la vez usando el símbolo <code>|</code>, y que imprima el mensaje indicado.<br><strong>Salida esperada:</strong> <code>Error de I/O o BD</code> (solo se imprime si el <code>try</code> lanza una de esas dos excepciones).', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'try {\n    // código\n} catch (IOException | SQLException e) {\n    System.out.println("Error de I/O o BD");\n}', hint: 'catch (Tipo1 | Tipo2 e) captura múltiples excepciones en un solo bloque.', validation: { requiredKeywords: ['|'] } },
    { id: 130, lessonId: 32, title: 'GetMessage', description: '<strong>Qué hacer:</strong> Estás dentro de <code>catch (Exception e) {</code>. Guarda <code>e.getMessage()</code> en una variable <code>String msg</code> e imprímela.<br><strong>Resultado esperado:</strong> se imprime el mensaje de la excepción capturada. Por ejemplo, si el error fue <code>new Exception("fallo")</code>, se imprime <code>fallo</code>.', difficulty: 'easy', starterCode: 'catch (Exception e) {', solution: 'String msg = e.getMessage();\nSystem.out.println(msg);', hint: 'e.getMessage() retorna el mensaje de la excepción.', validation: { requiredKeywords: ['getMessage'] } },
    { id: 131, lessonId: 31, title: 'PrintStackTrace', description: '<strong>Qué hacer:</strong> Estás dentro de <code>catch (Exception e) {</code>. Llama a <code>e.printStackTrace()</code> para mostrar la traza completa del error.<br><strong>Resultado esperado:</strong> se muestra en la consola de errores la traza de la excepción: su tipo, su mensaje y las líneas del código por donde pasó.', difficulty: 'easy', starterCode: 'catch (Exception e) {', solution: 'e.printStackTrace();', hint: 'printStackTrace() muestra la traza completa del error en consola.', validation: { requiredKeywords: ['printStackTrace'] } },
    { id: 132, lessonId: 32, title: 'Causa de Excepción', description: '<strong>Qué hacer:</strong> Escribe un <code>try</code> con un <code>catch (IOException e)</code>. Dentro del <code>catch</code>, lanza con <code>throw new</code> una <code>RuntimeException</code> con el mensaje <code>Error procesando</code> y pasa <code>e</code> como segundo argumento, para conservar la causa original.<br><strong>Resultado esperado:</strong> cuando el <code>try</code> falla con <code>IOException</code>, se lanza <code>RuntimeException: Error procesando</code> y su causa es la excepción original. No imprime nada.', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: 'try {\n    // código\n} catch (IOException e) {\n    throw new RuntimeException("Error procesando", e);\n}', hint: 'Pasa la excepción original como segundo parámetro para preservar la causa.', validation: { requiredKeywords: ['throw', 'new'] } },
    { id: 133, lessonId: 32, title: 'Assert', description: '<strong>Qué hacer:</strong> Considera que <code>int edad = -5;</code> ya está declarada. Escribe una aserción con <code>assert</code> que compruebe <code>edad &gt;= 0</code> y use el mensaje <code>Edad no puede ser negativa</code> (separado de la condición con <code>:</code>).<br><strong>Resultado esperado:</strong> si el programa corre con <code>-ea</code>, se lanza <code>AssertionError: Edad no puede ser negativa</code>. Sin esa opción las aserciones están desactivadas y no pasa nada.', difficulty: 'medium', starterCode: 'int edad = -5;', solution: 'assert edad >= 0 : "Edad no puede ser negativa";', hint: 'assert condición : mensaje; Lanza AssertionError si la condición es falsa.', validation: { requiredKeywords: ['assert'] } },
    { id: 134, lessonId: 31, title: 'NullPointerException', description: '<strong>Qué hacer:</strong> Considera que <code>String texto = null;</code> ya está declarada. Dentro de un <code>try</code>, guarda <code>texto.length()</code> en <code>int len</code>. Captura la <code>NullPointerException</code> con un <code>catch</code> que imprima el mensaje indicado.<br><strong>Salida esperada:</strong> <code>Texto es null</code>', difficulty: 'easy', starterCode: 'String texto = null;', solution: 'try {\n    int len = texto.length();\n} catch (NullPointerException e) {\n    System.out.println("Texto es null");\n}', hint: 'NullPointerException ocurre al usar métodos en objetos null.', validation: { requiredKeywords: ['NullPointerException'] } },
    { id: 135, lessonId: 37, title: 'Optional Empty', description: '<strong>Qué hacer:</strong> Con <code>java.util.Optional</code> ya importado, declara <code>Optional&lt;String&gt; opt</code> y asígnale un <code>Optional</code> vacío con <code>Optional.empty()</code>.<br><strong>Resultado esperado:</strong> la variable <code>opt</code> existe y no contiene valor. No imprime nada.', difficulty: 'easy', starterCode: 'import java.util.Optional;', solution: 'Optional<String> opt = Optional.empty();', hint: 'Optional.empty() crea un Optional sin valor.', validation: { requiredKeywords: ['Optional.empty'] } },
    { id: 136, lessonId: 37, title: 'Optional Of', description: '<strong>Qué hacer:</strong> Con <code>java.util.Optional</code> ya importado, declara <code>Optional&lt;String&gt; opt</code> y asígnale un <code>Optional</code> que contenga el texto <code>Hola</code>, usando <code>Optional.of</code>.<br><strong>Resultado esperado:</strong> la variable <code>opt</code> contiene <code>"Hola"</code>. No imprime nada.', difficulty: 'easy', starterCode: 'import java.util.Optional;', solution: 'Optional<String> opt = Optional.of("Hola");', hint: 'Optional.of(valor) crea un Optional con valor (lanza excepción si es null).', validation: { requiredKeywords: ['Optional.of'] } },
    { id: 137, lessonId: 37, title: 'Optional OfNullable', description: '<strong>Qué hacer:</strong> Considera que <code>String texto = null;</code> ya está declarada. Declara <code>Optional&lt;String&gt; opt</code> y créala a partir de <code>texto</code> con <code>Optional.ofNullable</code>, que acepta <code>null</code> sin lanzar error.<br><strong>Resultado esperado:</strong> <code>opt</code> queda vacío, porque <code>texto</code> es <code>null</code>. No imprime nada.', difficulty: 'medium', starterCode: 'String texto = null;', solution: 'Optional<String> opt = Optional.ofNullable(texto);', hint: 'ofNullable acepta null y crea Optional.empty() si es null.', validation: { requiredKeywords: ['ofNullable'] } },
    { id: 138, lessonId: 37, title: 'Optional IsPresent', description: '<strong>Qué hacer:</strong> Considera que <code>opt</code> ya vale <code>Optional.of("Hola")</code>. Con un <code>if</code>, comprueba <code>opt.isPresent()</code> y, si hay valor, imprímelo con <code>opt.get()</code>.<br><strong>Salida esperada:</strong> <code>Hola</code>', difficulty: 'easy', starterCode: 'Optional<String> opt = Optional.of("Hola");', solution: 'if (opt.isPresent()) {\n    System.out.println(opt.get());\n}', hint: 'isPresent() retorna true si hay valor. get() obtiene el valor.', validation: { requiredKeywords: ['isPresent', 'get'] } },
    { id: 139, lessonId: 37, title: 'Optional OrElse', description: '<strong>Qué hacer:</strong> Considera que <code>opt</code> ya es un <code>Optional&lt;String&gt;</code> vacío. Declara <code>String valor</code> y asígnale <code>opt.orElse("Defecto")</code>.<br><strong>Resultado esperado:</strong> <code>valor</code> vale <code>"Defecto"</code>, porque <code>opt</code> está vacío. No imprime nada.', difficulty: 'medium', starterCode: 'Optional<String> opt = Optional.empty();', solution: 'String valor = opt.orElse("Defecto");', hint: 'orElse(valorDefecto) retorna el valor o el defecto si está vacío.', validation: { requiredKeywords: ['orElse'] } },
    { id: 140, lessonId: 37, title: 'Optional IfPresent', description: '<strong>Qué hacer:</strong> Considera que <code>opt</code> ya vale <code>Optional.of("Hola")</code>. Llama a <code>opt.ifPresent(...)</code> pasándole una lambda con <code>-&gt;</code> que reciba <code>valor</code> y lo imprima.<br><strong>Salida esperada:</strong> <code>Hola</code>', difficulty: 'medium', starterCode: 'Optional<String> opt = Optional.of("Hola");', solution: 'opt.ifPresent(valor -> System.out.println(valor));', hint: 'ifPresent(lambda) ejecuta la lambda solo si hay valor.', validation: { requiredKeywords: ['ifPresent', '->'] } },

    // IDs 141-156: Programación Funcional y Lambdas
    { id: 141, lessonId: 34, title: 'Lambda Simple', description: '<strong>Qué hacer:</strong> Completa la asignación <code>Runnable r = </code> con una lambda (<code>-&gt;</code>) sin parámetros que imprima <code>Hola</code>. Termina con punto y coma.<br><strong>Resultado esperado:</strong> al ejecutar <code>r.run()</code> se imprime <code>Hola</code>. La lambda por sí sola no imprime nada.', difficulty: 'easy', starterCode: 'Runnable r = ', solution: '() -> System.out.println("Hola");', hint: 'Lambda: (parámetros) -> expresión. Sin parámetros: () -> código', validation: { requiredKeywords: ['->'] } },
    { id: 142, lessonId: 34, title: 'Lambda Con Parámetro', description: '<strong>Qué hacer:</strong> Completa la asignación <code>Consumer&lt;String&gt; c = </code> con una lambda (<code>-&gt;</code>) de un parámetro <code>s</code> que imprima ese texto con <code>System.out.println</code>. Termina con punto y coma.<br><strong>Resultado esperado:</strong> al ejecutar <code>c.accept("Hola")</code> se imprime <code>Hola</code>.', difficulty: 'easy', starterCode: 'Consumer<String> c = ', solution: 's -> System.out.println(s);', hint: 'Un parámetro: parámetro -> código (sin paréntesis)', validation: { requiredKeywords: ['->'] } },
    { id: 143, lessonId: 34, title: 'Lambda Múltiples Parámetros', description: '<strong>Qué hacer:</strong> Completa la asignación <code>BiFunction&lt;Integer, Integer, Integer&gt; suma = </code> con una lambda (<code>-&gt;</code>) de dos parámetros <code>a</code> y <code>b</code> que devuelva su suma. Termina con punto y coma.<br><strong>Resultado esperado:</strong> <code>suma.apply(2, 3)</code> devuelve <code>5</code>.', difficulty: 'medium', starterCode: 'BiFunction<Integer, Integer, Integer> suma = ', solution: '(a, b) -> a + b;', hint: 'Múltiples parámetros: (p1, p2) -> expresión', validation: { requiredKeywords: ['->'] } },
    { id: 144, lessonId: 34, title: 'Lambda Bloque', description: '<strong>Qué hacer:</strong> Completa la asignación <code>Consumer&lt;String&gt; c = </code> con una lambda de bloque (con llaves) de parámetro <code>s</code>: dentro, guarda <code>s.toUpperCase()</code> en una variable <code>String mayus</code> y luego imprímela. Termina con punto y coma.<br><strong>Resultado esperado:</strong> <code>c.accept("hola")</code> imprime <code>HOLA</code>.', difficulty: 'medium', starterCode: 'Consumer<String> c = ', solution: 's -> {\n    String mayus = s.toUpperCase();\n    System.out.println(mayus);\n};', hint: 'Bloque: parámetro -> { múltiples líneas }', validation: { requiredKeywords: ['->'] } },
    { id: 145, lessonId: 35, title: 'Predicate Test', description: '<strong>Qué hacer:</strong> Con <code>Predicate</code> ya importado, declara <code>Predicate&lt;Integer&gt; esPar</code> con una lambda que devuelva <code>true</code> si <code>n % 2 == 0</code>. Luego declara <code>boolean resultado</code> con <code>esPar.test(4)</code>.<br><strong>Resultado esperado:</strong> <code>resultado</code> vale <code>true</code>. No imprime nada.', difficulty: 'medium', starterCode: 'import java.util.function.Predicate;', solution: 'Predicate<Integer> esPar = n -> n % 2 == 0;\nboolean resultado = esPar.test(4);', hint: 'Predicate<T> tiene método test(T) que retorna boolean.', validation: { requiredKeywords: ['Predicate', 'test'] } },
    { id: 146, lessonId: 35, title: 'Function Apply', description: '<strong>Qué hacer:</strong> Con <code>Function</code> ya importado, declara <code>Function&lt;String, Integer&gt; longitud</code> con una lambda que devuelva la longitud de <code>s</code> (<code>s.length()</code>). Luego declara <code>int len</code> con <code>longitud.apply("Hola")</code>.<br><strong>Resultado esperado:</strong> <code>len</code> vale <code>4</code>. No imprime nada.', difficulty: 'medium', starterCode: 'import java.util.function.Function;', solution: 'Function<String, Integer> longitud = s -> s.length();\nint len = longitud.apply("Hola");', hint: 'Function<T, R> transforma T en R con apply(T).', validation: { requiredKeywords: ['Function', 'apply'] } },
    { id: 147, lessonId: 35, title: 'Consumer Accept', description: '<strong>Qué hacer:</strong> Con <code>Consumer</code> ya importado, declara <code>Consumer&lt;String&gt; imprimir</code> con una lambda que imprima su texto. Luego llámalo con <code>imprimir.accept("Hola")</code>.<br><strong>Salida esperada:</strong> <code>Hola</code>', difficulty: 'easy', starterCode: 'import java.util.function.Consumer;', solution: 'Consumer<String> imprimir = s -> System.out.println(s);\nimprimir.accept("Hola");', hint: 'Consumer<T> acepta T y no retorna nada. Usa accept(T).', validation: { requiredKeywords: ['Consumer', 'accept'] } },
    { id: 148, lessonId: 35, title: 'Supplier Get', description: '<strong>Qué hacer:</strong> Con <code>Supplier</code> ya importado, declara <code>Supplier&lt;Double&gt; random</code> con una lambda sin parámetros que devuelva <code>Math.random()</code>. Luego declara <code>double num</code> con <code>random.get()</code>.<br><strong>Resultado esperado:</strong> <code>num</code> es un número decimal aleatorio mayor o igual que 0 y menor que 1. No imprime nada.', difficulty: 'medium', starterCode: 'import java.util.function.Supplier;', solution: 'Supplier<Double> random = () -> Math.random();\ndouble num = random.get();', hint: 'Supplier<T> no recibe parámetros y retorna T con get().', validation: { requiredKeywords: ['Supplier', 'get'] } },
    { id: 149, lessonId: 36, title: 'Method Reference Static', description: '<strong>Qué hacer:</strong> Completa la asignación <code>Function&lt;String, Integer&gt; parser = </code> con una referencia al método estático <code>parseInt</code> de <code>Integer</code>, usando el operador <code>::</code>. Termina con punto y coma.<br><strong>Resultado esperado:</strong> <code>parser.apply("25")</code> devuelve el número <code>25</code>.', difficulty: 'medium', starterCode: 'Function<String, Integer> parser = ', solution: 'Integer::parseInt;', hint: 'Clase::métodoEstático es equivalente a s -> Clase.método(s)', validation: { requiredKeywords: ['::'] } },
    { id: 150, lessonId: 36, title: 'Method Reference Instance', description: '<strong>Qué hacer:</strong> Completa la asignación <code>Consumer&lt;String&gt; print = </code> con una referencia al método <code>println</code> de <code>System.out</code>, usando el operador <code>::</code>. Termina con punto y coma.<br><strong>Resultado esperado:</strong> <code>print.accept("Hola")</code> imprime <code>Hola</code>.', difficulty: 'medium', starterCode: 'Consumer<String> print = ', solution: 'System.out::println;', hint: 'objeto::método es equivalente a x -> objeto.método(x)', validation: { requiredKeywords: ['::'] } },
    { id: 151, lessonId: 36, title: 'Method Reference Constructor', description: '<strong>Qué hacer:</strong> Completa la asignación <code>Supplier&lt;ArrayList&lt;String&gt;&gt; listFactory = </code> con una referencia al constructor de <code>ArrayList</code> (<code>::new</code>). Termina con punto y coma.<br><strong>Resultado esperado:</strong> <code>listFactory.get()</code> devuelve una <code>ArrayList</code> nueva y vacía.', difficulty: 'hard', starterCode: 'Supplier<ArrayList<String>> listFactory = ', solution: 'ArrayList::new;', hint: 'Clase::new es equivalente a () -> new Clase()', validation: { requiredKeywords: ['::new'] } },
    { id: 152, lessonId: 38, title: 'Stream Filter', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya vale <code>[1, 2, 3, 4, 5]</code> (las importaciones necesarias ya están hechas). Declara <code>List&lt;Integer&gt; pares</code> usando <code>nums.stream()</code>, <code>filter</code> para dejar los números pares y <code>collect(Collectors.toList())</code>.<br><strong>Resultado esperado:</strong> <code>pares</code> contiene <code>[2, 4]</code>; si la imprimes, verás <code>[2, 4]</code>.', difficulty: 'medium', starterCode: 'List<Integer> nums = Arrays.asList(1,2,3,4,5);', solution: 'List<Integer> pares = nums.stream()\n    .filter(n -> n % 2 == 0)\n    .collect(Collectors.toList());', hint: 'filter(predicate) mantiene solo elementos que cumplen la condición.', validation: { requiredKeywords: ['filter', 'collect'] } },
    { id: 153, lessonId: 38, title: 'Stream Map', description: '<strong>Qué hacer:</strong> Considera que <code>nombres</code> ya vale <code>["Ana", "Luis"]</code> (las importaciones necesarias ya están hechas). Declara <code>List&lt;Integer&gt; longitudes</code> usando <code>nombres.stream()</code>, <code>map</code> para obtener la longitud de cada nombre y <code>collect(Collectors.toList())</code>.<br><strong>Resultado esperado:</strong> <code>longitudes</code> contiene <code>[3, 4]</code>; si la imprimes, verás <code>[3, 4]</code>.', difficulty: 'medium', starterCode: 'List<String> nombres = Arrays.asList("Ana", "Luis");', solution: 'List<Integer> longitudes = nombres.stream()\n    .map(s -> s.length())\n    .collect(Collectors.toList());', hint: 'map(function) transforma cada elemento aplicando la función.', validation: { requiredKeywords: ['map', 'collect'] } },
    { id: 154, lessonId: 38, title: 'Stream ForEach', description: '<strong>Qué hacer:</strong> Considera que <code>lista</code> ya vale <code>["A", "B", "C"]</code> (las importaciones necesarias ya están hechas). Recórrela con <code>lista.stream().forEach(...)</code> y una lambda que imprima cada elemento.<br><strong>Salida esperada:</strong> <code>A</code>, <code>B</code> y <code>C</code>, cada uno en su propia línea.', difficulty: 'easy', starterCode: 'List<String> lista = Arrays.asList("A", "B", "C");', solution: 'lista.stream().forEach(s -> System.out.println(s));', hint: 'forEach(consumer) ejecuta una acción para cada elemento.', validation: { requiredKeywords: ['forEach'] } },
    { id: 155, lessonId: 39, title: 'Stream Count', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya vale <code>[1, 2, 3, 4, 5]</code> (las importaciones necesarias ya están hechas). Declara <code>long cantidad</code> con el número de elementos, usando <code>nums.stream().count()</code>.<br><strong>Resultado esperado:</strong> <code>cantidad</code> vale <code>5</code>. No imprime nada.', difficulty: 'easy', starterCode: 'List<Integer> nums = Arrays.asList(1,2,3,4,5);', solution: 'long cantidad = nums.stream().count();', hint: 'count() retorna el número de elementos en el stream.', validation: { requiredKeywords: ['count'] } },
    { id: 156, lessonId: 39, title: 'Stream Reduce', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya vale <code>[1, 2, 3, 4, 5]</code> (las importaciones necesarias ya están hechas). Declara <code>int suma</code> usando <code>nums.stream()</code> y <code>reduce</code> con valor inicial <code>0</code> y una lambda <code>(a, b)</code> que sume ambos.<br><strong>Resultado esperado:</strong> <code>suma</code> vale <code>15</code>. No imprime nada.', difficulty: 'hard', starterCode: 'List<Integer> nums = Arrays.asList(1,2,3,4,5);', solution: 'int suma = nums.stream()\n    .reduce(0, (a, b) -> a + b);', hint: 'reduce(inicial, acumulador) combina elementos. Ejemplo: suma.', validation: { requiredKeywords: ['reduce'] } },

    // IDs 157-168: Streams avanzados e I/O
    { id: 157, lessonId: 38, title: 'Stream Sorted', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya vale <code>[5, 2, 8, 1]</code> (las importaciones necesarias ya están hechas). Declara <code>List&lt;Integer&gt; ordenados</code> usando <code>nums.stream()</code>, <code>sorted()</code> y <code>collect(Collectors.toList())</code>.<br><strong>Resultado esperado:</strong> <code>ordenados</code> contiene <code>[1, 2, 5, 8]</code>; si la imprimes, verás <code>[1, 2, 5, 8]</code>.', difficulty: 'easy', starterCode: 'List<Integer> nums = Arrays.asList(5,2,8,1);', solution: 'List<Integer> ordenados = nums.stream()\n    .sorted()\n    .collect(Collectors.toList());', hint: 'sorted() ordena los elementos en orden natural.', validation: { requiredKeywords: ['sorted'] } },
    { id: 158, lessonId: 38, title: 'Stream Distinct', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya vale <code>[1, 2, 2, 3, 3, 3]</code> (las importaciones necesarias ya están hechas). Declara <code>List&lt;Integer&gt; unicos</code> usando <code>nums.stream()</code>, <code>distinct()</code> y <code>collect(Collectors.toList())</code>.<br><strong>Resultado esperado:</strong> <code>unicos</code> contiene <code>[1, 2, 3]</code>; si la imprimes, verás <code>[1, 2, 3]</code>.', difficulty: 'easy', starterCode: 'List<Integer> nums = Arrays.asList(1,2,2,3,3,3);', solution: 'List<Integer> unicos = nums.stream()\n    .distinct()\n    .collect(Collectors.toList());', hint: 'distinct() elimina elementos duplicados.', validation: { requiredKeywords: ['distinct'] } },
    { id: 159, lessonId: 38, title: 'Stream Limit', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya vale <code>[1, 2, 3, 4, 5]</code> (las importaciones necesarias ya están hechas). Declara <code>List&lt;Integer&gt; primeros</code> usando <code>nums.stream()</code>, <code>limit(3)</code> y <code>collect(Collectors.toList())</code>.<br><strong>Resultado esperado:</strong> <code>primeros</code> contiene <code>[1, 2, 3]</code>; si la imprimes, verás <code>[1, 2, 3]</code>.', difficulty: 'easy', starterCode: 'List<Integer> nums = Arrays.asList(1,2,3,4,5);', solution: 'List<Integer> primeros = nums.stream()\n    .limit(3)\n    .collect(Collectors.toList());', hint: 'limit(n) toma solo los primeros n elementos.', validation: { requiredKeywords: ['limit'] } },
    { id: 160, lessonId: 39, title: 'Stream AnyMatch', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya vale <code>[1, 2, 3, 4, 5]</code> (las importaciones necesarias ya están hechas). Declara <code>boolean hayPar</code> usando <code>nums.stream()</code> y <code>anyMatch</code> con una lambda que compruebe si el número es par.<br><strong>Resultado esperado:</strong> <code>hayPar</code> vale <code>true</code>. No imprime nada.', difficulty: 'medium', starterCode: 'List<Integer> nums = Arrays.asList(1,2,3,4,5);', solution: 'boolean hayPar = nums.stream()\n    .anyMatch(n -> n % 2 == 0);', hint: 'anyMatch(predicate) retorna true si al menos uno cumple.', validation: { requiredKeywords: ['anyMatch'] } },
    { id: 161, lessonId: 39, title: 'Stream AllMatch', description: '<strong>Qué hacer:</strong> Considera que <code>nums</code> ya vale <code>[2, 4, 6, 8]</code> (las importaciones necesarias ya están hechas). Declara <code>boolean todosPares</code> usando <code>nums.stream()</code> y <code>allMatch</code> con una lambda que compruebe si el número es par.<br><strong>Resultado esperado:</strong> <code>todosPares</code> vale <code>true</code>. No imprime nada.', difficulty: 'medium', starterCode: 'List<Integer> nums = Arrays.asList(2,4,6,8);', solution: 'boolean todosPares = nums.stream()\n    .allMatch(n -> n % 2 == 0);', hint: 'allMatch(predicate) retorna true si todos cumplen.', validation: { requiredKeywords: ['allMatch'] } },
    { id: 162, lessonId: 41, title: 'File Write', description: '<strong>Qué hacer:</strong> Con <code>java.nio.file.*</code> ya importado, declara <code>String contenido = "Hola Mundo";</code> y escríbelo en el archivo <code>archivo.txt</code> con <code>Files.writeString(Path.of("archivo.txt"), contenido)</code>. Considera que el código está en un método que ya declara <code>throws IOException</code>.<br><strong>Resultado esperado:</strong> se crea <code>archivo.txt</code> con el texto <code>Hola Mundo</code>. No imprime nada.', difficulty: 'medium', starterCode: 'import java.nio.file.*;', solution: 'String contenido = "Hola Mundo";\nFiles.writeString(Path.of("archivo.txt"), contenido);', hint: 'Files.writeString(path, contenido) escribe texto a un archivo.', validation: { requiredKeywords: ['Files.writeString'] } },
    { id: 163, lessonId: 41, title: 'File Read', description: '<strong>Qué hacer:</strong> Con <code>java.nio.file.*</code> ya importado, lee todo el archivo <code>archivo.txt</code> con <code>Files.readString(Path.of("archivo.txt"))</code> y guarda el resultado en <code>String contenido</code>. Considera que el código está en un método que ya declara <code>throws IOException</code>.<br><strong>Resultado esperado:</strong> <code>contenido</code> tiene el texto del archivo (por ejemplo <code>Hola Mundo</code> si lo creaste antes). No imprime nada. Si <code>archivo.txt</code> no existe, se lanza <code>NoSuchFileException</code>.', difficulty: 'medium', starterCode: 'import java.nio.file.*;', solution: 'String contenido = Files.readString(Path.of("archivo.txt"));', hint: 'Files.readString(path) lee todo el contenido como String.', validation: { requiredKeywords: ['Files.readString'] } },
    { id: 164, lessonId: 41, title: 'File Exists', description: '<strong>Qué hacer:</strong> Con <code>java.nio.file.*</code> ya importado, declara <code>boolean existe</code> con el resultado de <code>Files.exists(Path.of("archivo.txt"))</code>.<br><strong>Resultado esperado:</strong> <code>existe</code> vale <code>true</code> si <code>archivo.txt</code> existe y <code>false</code> si no. No imprime nada.', difficulty: 'easy', starterCode: 'import java.nio.file.*;', solution: 'boolean existe = Files.exists(Path.of("archivo.txt"));', hint: 'Files.exists(path) retorna true si el archivo existe.', validation: { requiredKeywords: ['Files.exists'] } },
    { id: 165, lessonId: 41, title: 'File Delete', description: '<strong>Qué hacer:</strong> Con <code>java.nio.file.*</code> ya importado, borra el archivo <code>archivo.txt</code> con <code>Files.deleteIfExists(Path.of("archivo.txt"))</code>. Considera que el código está en un método que ya declara <code>throws IOException</code>.<br><strong>Resultado esperado:</strong> <code>archivo.txt</code> deja de existir; si no existía, no pasa nada. No imprime nada.', difficulty: 'easy', starterCode: 'import java.nio.file.*;', solution: 'Files.deleteIfExists(Path.of("archivo.txt"));', hint: 'Files.deleteIfExists(path) elimina el archivo si existe.', validation: { requiredKeywords: ['deleteIfExists'] } },
    { id: 166, lessonId: 41, title: 'BufferedReader', description: '<strong>Qué hacer:</strong> Con <code>java.io.*</code> ya importado, lee <code>file.txt</code> línea por línea. Abre un <code>BufferedReader</code> (sobre un <code>FileReader</code>) en el paréntesis de un <code>try-with-resources</code>. Con un bucle <code>while</code>, guarda <code>br.readLine()</code> en <code>String linea</code> hasta que sea <code>null</code>, e imprime cada línea. Considera que el código está en un método que ya declara <code>throws IOException</code>.<br><strong>Salida esperada:</strong> el contenido de <code>file.txt</code>, una línea por línea. Si el archivo contiene <code>Hola</code> y <code>Java</code> en dos líneas, verás esas dos líneas.', difficulty: 'hard', starterCode: 'import java.io.*;', solution: 'try (BufferedReader br = new BufferedReader(new FileReader("file.txt"))) {\n    String linea;\n    while ((linea = br.readLine()) != null) {\n        System.out.println(linea);\n    }\n}', hint: 'BufferedReader.readLine() lee una línea. Retorna null al final.', validation: { requiredKeywords: ['BufferedReader', 'readLine'] } },
    { id: 167, lessonId: 41, title: 'BufferedWriter', description: '<strong>Qué hacer:</strong> Con <code>java.io.*</code> ya importado, escribe dos líneas en <code>file.txt</code>. Abre un <code>BufferedWriter</code> (sobre un <code>FileWriter</code>) en el paréntesis de un <code>try-with-resources</code>. Usa <code>write("Línea 1")</code>, luego <code>newLine()</code> y luego <code>write("Línea 2")</code>. Considera que el código está en un método que ya declara <code>throws IOException</code>.<br><strong>Resultado esperado:</strong> <code>file.txt</code> contiene <code>Línea 1</code> y <code>Línea 2</code> en dos líneas distintas. No imprime nada.', difficulty: 'medium', starterCode: 'import java.io.*;', solution: 'try (BufferedWriter bw = new BufferedWriter(new FileWriter("file.txt"))) {\n    bw.write("Línea 1");\n    bw.newLine();\n    bw.write("Línea 2");\n}', hint: 'BufferedWriter.write() escribe texto. newLine() agrega salto de línea.', validation: { requiredKeywords: ['BufferedWriter', 'write'] } },
    { id: 168, lessonId: 41, title: 'Files Lines Stream', description: '<strong>Qué hacer:</strong> Con <code>java.nio.file.*</code> ya importado (y <code>java.util.stream.Stream</code>), abre <code>Files.lines(Path.of("file.txt"))</code> como <code>Stream&lt;String&gt; lineas</code> dentro de un <code>try-with-resources</code>. Con <code>filter</code> deja solo las líneas que contengan <code>Java</code> (<code>l.contains("Java")</code>) y muéstralas con <code>forEach(System.out::println)</code>. Considera que el código está en un método que ya declara <code>throws IOException</code>.<br><strong>Salida esperada:</strong> solo las líneas de <code>file.txt</code> que contienen la palabra <code>Java</code>. Si el archivo tiene <code>Java es genial</code> y <code>Python es popular</code>, se imprime <code>Java es genial</code>.', difficulty: 'hard', starterCode: 'import java.nio.file.*;', solution: 'try (Stream<String> lineas = Files.lines(Path.of("file.txt"))) {\n    lineas.filter(l -> l.contains("Java"))\n          .forEach(System.out::println);\n}', hint: 'Files.lines(path) retorna Stream<String> de líneas del archivo.', validation: { requiredKeywords: ['Files.lines', 'Stream'] } },

    // IDs 169-208: EXPERTO (Threads, Patterns, SOLID, TDD)
    // IDs 169-188: Threads y Concurrencia
    { id: 169, lessonId: 43, title: 'Thread Extends', description: '<strong>Qué hacer:</strong> Crea la clase pública <code>MiThread</code> que <code>extends Thread</code> y sobrescribe el método <code>run()</code> para que imprima <code>Ejecutando</code> con <code>System.out.println</code>. No hace falta <code>main</code>.<br><strong>Resultado esperado:</strong> una clase <code>MiThread</code> que extiende <code>Thread</code> con <code>run()</code>; al crear una instancia y llamar a <code>start()</code>, se vería <code>Ejecutando</code>.', difficulty: 'medium', starterCode: '// Escribe tu programa completo aquí', solution: 'public class MiThread extends Thread {\n    public void run() {\n        System.out.println("Ejecutando");\n    }\n}', hint: 'Extiende Thread y sobrescribe run(). Inicia con start().', validation: { requiredKeywords: ['extends', 'Thread', 'run'] } },
    { id: 170, lessonId: 43, title: 'Runnable Interface', description: '<strong>Qué hacer:</strong> Crea la clase pública <code>MiRunnable</code> que <code>implements Runnable</code> y define el método <code>run()</code> para que imprima <code>Ejecutando</code>. No hace falta <code>main</code>.<br><strong>Resultado esperado:</strong> una clase <code>MiRunnable</code> que implementa <code>Runnable</code>; con <code>new Thread(new MiRunnable()).start()</code> se vería <code>Ejecutando</code>.', difficulty: 'medium', starterCode: '// Escribe tu programa completo aquí', solution: 'public class MiRunnable implements Runnable {\n    public void run() {\n        System.out.println("Ejecutando");\n    }\n}', hint: 'Implementa Runnable y define run(). Crea Thread: new Thread(runnable).start()', validation: { requiredKeywords: ['implements', 'Runnable'] } },
    { id: 171, lessonId: 43, title: 'Thread Start', description: '<strong>Qué hacer:</strong> Considera que ya existe la variable <code>t</code>: <code>Thread t = new Thread(() -&gt; System.out.println("Hola"));</code>. Escribe la línea que inicia ese hilo llamando a su método <code>start()</code> (no a <code>run()</code>).<br><strong>Salida esperada:</strong> <code>Hola</code> (aparece una vez cuando el fragmento se ejecuta dentro de un programa completo).', difficulty: 'easy', starterCode: 'Thread t = new Thread(() -> System.out.println("Hola"));', solution: 't.start();', hint: 'start() inicia el thread. NO llames run() directamente.', validation: { requiredKeywords: ['start'] } },
    { id: 172, lessonId: 43, title: 'Thread Sleep', description: '<strong>Qué hacer:</strong> Escribe un bloque <code>try</code>/<code>catch</code> que pause el hilo actual 1000 milisegundos con <code>Thread.sleep(1000)</code> y capture <code>InterruptedException e</code> mostrando <code>e.printStackTrace()</code>.<br><strong>Resultado esperado:</strong> el programa se detiene 1 segundo y no imprime nada.', difficulty: 'easy', starterCode: '// Escribe tu código aquí', solution: 'try {\n    Thread.sleep(1000);\n} catch (InterruptedException e) {\n    e.printStackTrace();\n}', hint: 'Thread.sleep(milisegundos) pausa el thread actual.', validation: { requiredKeywords: ['Thread.sleep'] } },
    { id: 173, lessonId: 43, title: 'Thread Join', description: '<strong>Qué hacer:</strong> Considera que ya existe <code>Thread t = new Thread(() -&gt; {});</code>. Inícialo con <code>t.start();</code> y luego espera a que termine con <code>t.join()</code>, dentro de un <code>try</code>/<code>catch (InterruptedException e)</code> que llame a <code>e.printStackTrace()</code>.<br><strong>Resultado esperado:</strong> el programa espera a que <code>t</code> termine y no imprime nada.', difficulty: 'medium', starterCode: 'Thread t = new Thread(() -> {});', solution: 't.start();\ntry {\n    t.join();\n} catch (InterruptedException e) {\n    e.printStackTrace();\n}', hint: 'join() espera a que el thread termine antes de continuar.', validation: { requiredKeywords: ['join'] } },
    { id: 174, lessonId: 44, title: 'Synchronized Method', description: '<strong>Qué hacer:</strong> Considera que la clase ya tiene el campo <code>private int contador = 0;</code>. Agrega el método <code>public synchronized void incrementar()</code> que haga <code>contador++</code>.<br><strong>Resultado esperado:</strong> un método <code>incrementar()</code> marcado con <code>synchronized</code>, de modo que solo un hilo a la vez pueda incrementar <code>contador</code>.', difficulty: 'hard', starterCode: 'private int contador = 0;', solution: 'public synchronized void incrementar() {\n    contador++;\n}', hint: 'synchronized evita que múltiples threads ejecuten el método simultáneamente.', validation: { requiredKeywords: ['synchronized'] } },
    { id: 175, lessonId: 44, title: 'Synchronized Block', description: '<strong>Qué hacer:</strong> Considera que ya existe un objeto <code>lock</code> (un <code>Object</code>). Escribe un bloque <code>synchronized</code> que use <code>lock</code> como candado y, dentro del bloque, el comentario <code>// código crítico</code>.<br><strong>Resultado esperado:</strong> un bloque <code>synchronized</code> que usa <code>lock</code> como candado (no imprime nada).', difficulty: 'hard', starterCode: 'private Object lock = new Object();', solution: 'synchronized (lock) {\n    // código crítico\n}', hint: 'synchronized (objeto) { } sincroniza solo ese bloque.', validation: { requiredKeywords: ['synchronized'] } },
    { id: 176, lessonId: 44, title: 'Volatile Variable', description: '<strong>Qué hacer:</strong> Declara un campo privado de tipo <code>boolean</code> llamado <code>activo</code>, con valor inicial <code>true</code>, que todos los hilos vean actualizado al instante (para eso se usa el modificador <code>volatile</code>).<br><strong>Resultado esperado:</strong> una declaración de <code>activo</code> con el modificador <code>volatile</code>, inicializada en <code>true</code> (no imprime nada).', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: 'private volatile boolean activo = true;', hint: 'volatile asegura que todos los threads vean el valor más reciente.', validation: { requiredKeywords: ['volatile'] } },
    { id: 177, lessonId: 44, title: 'AtomicInteger', description: '<strong>Qué hacer:</strong> Con el import de <code>java.util.concurrent.atomic</code> ya escrito, declara un <code>AtomicInteger</code> llamado <code>contador</code> que empiece en 0 y súmale uno de forma segura con su método <code>incrementAndGet()</code>.<br><strong>Resultado esperado:</strong> tras la segunda línea, <code>contador</code> vale 1 (no imprime nada).', difficulty: 'medium', starterCode: 'import java.util.concurrent.atomic.*;', solution: 'AtomicInteger contador = new AtomicInteger(0);\ncontador.incrementAndGet();', hint: 'AtomicInteger provee operaciones thread-safe sin synchronized.', validation: { requiredKeywords: ['AtomicInteger'] } },
    { id: 178, lessonId: 45, title: 'ExecutorService', description: '<strong>Qué hacer:</strong> Crea un <code>ExecutorService executor</code> con <code>Executors.newFixedThreadPool(5)</code>, envíale con <code>submit</code> una lambda que imprima <code>Tarea</code> y ciérralo con <code>executor.shutdown()</code>.<br><strong>Salida esperada:</strong> <code>Tarea</code>', difficulty: 'hard', starterCode: 'import java.util.concurrent.*;', solution: 'ExecutorService executor = Executors.newFixedThreadPool(5);\nexecutor.submit(() -> System.out.println("Tarea"));\nexecutor.shutdown();', hint: 'ExecutorService maneja un pool de threads. Usa shutdown() al terminar.', validation: { requiredKeywords: ['ExecutorService', 'submit'] } },
    { id: 179, lessonId: 45, title: 'Callable Future', description: '<strong>Qué hacer:</strong> Considera que ya existe un <code>ExecutorService executor</code>. Declara <code>Callable&lt;Integer&gt; tarea = () -&gt; 42;</code>, envíala con <code>executor.submit(tarea)</code> guardando el <code>Future&lt;Integer&gt; futuro</code>, y lee el valor con <code>int resultado = futuro.get();</code> (<code>get()</code> lanza excepciones comprobadas: en un programa real va en un método con <code>throws Exception</code>).<br><strong>Resultado esperado:</strong> <code>resultado</code> vale <code>42</code> (el fragmento no imprime nada).', difficulty: 'hard', starterCode: 'import java.util.concurrent.*;', solution: 'Callable<Integer> tarea = () -> 42;\nFuture<Integer> futuro = executor.submit(tarea);\nint resultado = futuro.get();', hint: 'Callable retorna valor. Future.get() espera y obtiene el resultado.', validation: { requiredKeywords: ['Callable', 'Future', 'get'] } },
    { id: 180, lessonId: 46, title: 'CompletableFuture', description: '<strong>Qué hacer:</strong> Encadena con <code>CompletableFuture.supplyAsync(() -&gt; "Hola")</code>, luego <code>.thenApply</code> para agregar <code>" Mundo"</code> al texto y por último <code>.thenAccept(System.out::println)</code>. Si pruebas en un programa completo, termina la cadena con <code>.join()</code> para que <code>main</code> espere el resultado.<br><strong>Salida esperada:</strong> <code>Hola Mundo</code>', difficulty: 'hard', starterCode: 'import java.util.concurrent.*;', solution: 'CompletableFuture.supplyAsync(() -> "Hola")\n    .thenApply(s -> s + " Mundo")\n    .thenAccept(System.out::println);', hint: 'CompletableFuture permite encadenar operaciones asíncronas.', validation: { requiredKeywords: ['CompletableFuture', 'thenApply'] } },
    { id: 181, lessonId: 45, title: 'CountDownLatch', description: '<strong>Qué hacer:</strong> Crea un <code>CountDownLatch</code> llamado <code>latch</code> con cuenta inicial 3, agrega un comentario que diga que cada hilo debe llamar a <code>countDown()</code> y llama al método <code>await()</code> del latch. Ojo: en un programa real <code>await()</code> espera para siempre si ningún hilo llama a <code>countDown()</code> tres veces, y lanza <code>InterruptedException</code>.<br><strong>Resultado esperado:</strong> <code>latch</code> con cuenta inicial 3; la espera termina cuando los hilos hayan llamado a <code>countDown()</code> tres veces.', difficulty: 'hard', starterCode: 'import java.util.concurrent.*;', solution: 'CountDownLatch latch = new CountDownLatch(3);\n// En cada thread: latch.countDown();\nlatch.await();', hint: 'CountDownLatch espera hasta que N threads llamen countDown().', validation: { requiredKeywords: ['CountDownLatch', 'await'] } },
    { id: 182, lessonId: 45, title: 'CyclicBarrier', description: '<strong>Qué hacer:</strong> Crea una <code>CyclicBarrier</code> llamada <code>barrier</code> para 3 hilos y agrega un comentario que diga que cada hilo llamará a <code>await()</code> en la barrera.<br><strong>Resultado esperado:</strong> una barrera <code>barrier</code> para 3 hilos (no imprime nada).', difficulty: 'hard', starterCode: 'import java.util.concurrent.*;', solution: 'CyclicBarrier barrier = new CyclicBarrier(3);\n// En cada thread: barrier.await();', hint: 'CyclicBarrier sincroniza N threads en un punto común.', validation: { requiredKeywords: ['CyclicBarrier'] } },
    { id: 183, lessonId: 45, title: 'Semaphore', description: '<strong>Qué hacer:</strong> Crea un <code>Semaphore</code> llamado <code>semaphore</code> con 3 permisos. Pide un permiso con <code>acquire()</code>, abre un <code>try</code> con el comentario <code>// código</code> y, en el <code>finally</code>, devuelve el permiso con <code>release()</code>. (<code>acquire()</code> lanza <code>InterruptedException</code>: va dentro de un método que la declare con <code>throws</code>.)<br><strong>Resultado esperado:</strong> un semáforo de 3 permisos que se toma antes del <code>try</code> y se libera siempre en el <code>finally</code> (no imprime nada).', difficulty: 'hard', starterCode: 'import java.util.concurrent.*;', solution: 'Semaphore semaphore = new Semaphore(3);\nsemaphore.acquire();\ntry {\n    // código\n} finally {\n    semaphore.release();\n}', hint: 'Semaphore limita cuántos threads pueden acceder simultáneamente.', validation: { requiredKeywords: ['Semaphore', 'acquire', 'release'] } },
    { id: 184, lessonId: 44, title: 'ConcurrentHashMap', description: '<strong>Qué hacer:</strong> Declara <code>ConcurrentHashMap&lt;String, Integer&gt; map = new ConcurrentHashMap&lt;&gt;();</code> y agrega la entrada <code>"clave"</code> con valor <code>1</code> usando <code>map.put</code>.<br><strong>Resultado esperado:</strong> un mapa con una entrada <code>clave=1</code> (no imprime nada).', difficulty: 'medium', starterCode: 'import java.util.concurrent.*;', solution: 'ConcurrentHashMap<String, Integer> map = new ConcurrentHashMap<>();\nmap.put("clave", 1);', hint: 'ConcurrentHashMap es thread-safe sin sincronizar todo el map.', validation: { requiredKeywords: ['ConcurrentHashMap'] } },
    { id: 185, lessonId: 44, title: 'CopyOnWriteArrayList', description: '<strong>Qué hacer:</strong> Declara <code>CopyOnWriteArrayList&lt;String&gt; lista = new CopyOnWriteArrayList&lt;&gt;();</code> y agrega el texto <code>"elemento"</code> con <code>lista.add</code>.<br><strong>Resultado esperado:</strong> una lista que contiene un elemento, <code>elemento</code> (no imprime nada).', difficulty: 'medium', starterCode: 'import java.util.concurrent.*;', solution: 'CopyOnWriteArrayList<String> lista = new CopyOnWriteArrayList<>();\nlista.add("elemento");', hint: 'CopyOnWriteArrayList es thread-safe, ideal para más lecturas que escrituras.', validation: { requiredKeywords: ['CopyOnWriteArrayList'] } },
    { id: 186, lessonId: 44, title: 'BlockingQueue', description: '<strong>Qué hacer:</strong> Declara <code>BlockingQueue&lt;String&gt; cola = new ArrayBlockingQueue&lt;&gt;(10);</code>, inserta <code>"elemento"</code> con <code>cola.put</code> y sácalo con <code>String item = cola.take();</code> (ambos lanzan <code>InterruptedException</code>: van en un método con <code>throws</code>).<br><strong>Resultado esperado:</strong> <code>item</code> vale <code>elemento</code> y la cola queda vacía (no imprime nada).', difficulty: 'hard', starterCode: 'import java.util.concurrent.*;', solution: 'BlockingQueue<String> cola = new ArrayBlockingQueue<>(10);\ncola.put("elemento");\nString item = cola.take();', hint: 'BlockingQueue bloquea si está llena (put) o vacía (take).', validation: { requiredKeywords: ['BlockingQueue', 'put', 'take'] } },
    { id: 187, lessonId: 44, title: 'ReentrantLock', description: '<strong>Qué hacer:</strong> Crea un <code>ReentrantLock</code> llamado <code>lock</code>. Tómalo con su método <code>lock()</code>, abre un <code>try</code> con el comentario <code>// código crítico</code> y suéltalo en el <code>finally</code> con <code>unlock()</code>.<br><strong>Resultado esperado:</strong> un candado que se toma con <code>lock()</code> y se libera siempre con <code>unlock()</code> en el <code>finally</code> (no imprime nada).', difficulty: 'hard', starterCode: 'import java.util.concurrent.locks.*;', solution: 'ReentrantLock lock = new ReentrantLock();\nlock.lock();\ntry {\n    // código crítico\n} finally {\n    lock.unlock();\n}', hint: 'ReentrantLock es más flexible que synchronized. Siempre unlock en finally.', validation: { requiredKeywords: ['ReentrantLock', 'lock', 'unlock'] } },
    { id: 188, lessonId: 44, title: 'ReadWriteLock', description: '<strong>Qué hacer:</strong> Crea un <code>ReadWriteLock</code> llamado <code>rwLock</code> (la implementación es <code>ReentrantReadWriteLock</code>). Toma el candado de lectura con <code>readLock().lock()</code>, abre un <code>try</code> con el comentario <code>// lectura</code> y libéralo en el <code>finally</code> con <code>readLock().unlock()</code>.<br><strong>Resultado esperado:</strong> un bloque de lectura protegido por <code>readLock()</code> y liberado en el <code>finally</code> (no imprime nada).', difficulty: 'hard', starterCode: 'import java.util.concurrent.locks.*;', solution: 'ReadWriteLock rwLock = new ReentrantReadWriteLock();\nrwLock.readLock().lock();\ntry {\n    // lectura\n} finally {\n    rwLock.readLock().unlock();\n}', hint: 'ReadWriteLock permite múltiples lectores o un escritor.', validation: { requiredKeywords: ['ReadWriteLock', 'readLock'] } },

    // IDs 189-208: Patterns, SOLID, TDD
    { id: 189, lessonId: 47, title: 'Singleton Pattern', description: '<strong>Qué hacer:</strong> Escribe la clase <code>Singleton</code> con un campo <code>private static Singleton instancia;</code>, un constructor <code>private</code> vacío y un método <code>public static Singleton getInstancia()</code> que cree la instancia solo si es <code>null</code> y la devuelva.<br><strong>Resultado esperado:</strong> una clase <code>Singleton</code> cuyo único constructor es privado y donde <code>getInstancia()</code> devuelve siempre el mismo objeto (no imprime nada).', difficulty: 'hard', starterCode: '// Escribe tu programa completo aquí', solution: 'public class Singleton {\n    private static Singleton instancia;\n    private Singleton() {}\n    public static Singleton getInstancia() {\n        if (instancia == null) {\n            instancia = new Singleton();\n        }\n        return instancia;\n    }\n}', hint: 'Constructor privado + método estático que retorna la única instancia.', validation: { requiredKeywords: ['private', 'static'] } },
    { id: 190, lessonId: 47, title: 'Factory Pattern', description: '<strong>Qué hacer:</strong> Considera que ya existen la clase <code>Animal</code> y sus subclases <code>Perro</code> y <code>Gato</code>. Escribe la clase <code>AnimalFactory</code> con el método <code>public static Animal crear(String tipo)</code>: si <code>tipo</code> es <code>"perro"</code> devuelve un <code>new Perro()</code>, si es <code>"gato"</code> un <code>new Gato()</code>, y en otro caso devuelve <code>null</code> (usa <code>return</code>).<br><strong>Resultado esperado:</strong> <code>AnimalFactory.crear("perro")</code> devuelve un <code>Perro</code>, <code>crear("gato")</code> un <code>Gato</code> y cualquier otro texto <code>null</code>.', difficulty: 'hard', starterCode: '// Escribe tu programa completo aquí', solution: 'public class AnimalFactory {\n    public static Animal crear(String tipo) {\n        if (tipo.equals("perro")) return new Perro();\n        if (tipo.equals("gato")) return new Gato();\n        return null;\n    }\n}', hint: 'Factory encapsula la creación de objetos según parámetros.', validation: { requiredKeywords: ['static', 'return'] } },
    { id: 191, lessonId: 47, title: 'Builder Pattern', description: '<strong>Qué hacer:</strong> Escribe la clase <code>Persona</code> con campos <code>private String nombre</code> y <code>private int edad</code>, y dentro la clase anidada <code>public static class Builder</code>. El <code>Builder</code> guarda un <code>Persona p = new Persona()</code>, tiene <code>nombre(String n)</code> que asigna el nombre y termina con <code>return this</code>, y <code>build()</code> que devuelve <code>p</code>.<br><strong>Resultado esperado:</strong> <code>new Persona.Builder().nombre("Ana").build()</code> devuelve una <code>Persona</code> con ese nombre (no imprime nada).', difficulty: 'hard', starterCode: '// Escribe tu programa completo aquí', solution: 'public class Persona {\n    private String nombre;\n    private int edad;\n    public static class Builder {\n        private Persona p = new Persona();\n        public Builder nombre(String n) {\n            p.nombre = n;\n            return this;\n        }\n        public Persona build() { return p; }\n    }\n}', hint: 'Builder permite construir objetos paso a paso con sintaxis fluida.', validation: { requiredKeywords: ['Builder', 'return this'] } },
    { id: 192, lessonId: 49, title: 'Observer Pattern', description: '<strong>Qué hacer:</strong> Define la interfaz <code>Observer</code> con <code>void actualizar(String evento)</code> y la clase <code>Sujeto</code> con una lista privada <code>observadores</code> (<code>List&lt;Observer&gt;</code> con <code>ArrayList</code>; agrega <code>import java.util.*;</code>), el método <code>agregar(Observer o)</code> y <code>notificar(String evento)</code>, que recorre la lista con <code>forEach</code> llamando a <code>actualizar</code>.<br><strong>Resultado esperado:</strong> dos interfaces/clases (<code>Observer</code> y <code>Sujeto</code>) donde <code>notificar</code> avisa a todos los observadores agregados (no imprime nada por sí solo).', difficulty: 'hard', starterCode: '// Escribe tu programa completo aquí', solution: 'interface Observer {\n    void actualizar(String evento);\n}\nclass Sujeto {\n    private List<Observer> observadores = new ArrayList<>();\n    public void agregar(Observer o) { observadores.add(o); }\n    public void notificar(String evento) {\n        observadores.forEach(o -> o.actualizar(evento));\n    }\n}', hint: 'Observer: sujeto notifica a múltiples observadores cuando cambia.', validation: { requiredKeywords: ['interface', 'forEach'] } },
    { id: 193, lessonId: 49, title: 'Strategy Pattern', description: '<strong>Qué hacer:</strong> Define la <code>interface Estrategia</code> con <code>int calcular(int a, int b)</code>; la clase <code>Suma</code> que <code>implements Estrategia</code> y devuelve <code>a + b</code>; y la clase <code>Contexto</code> con un campo <code>private Estrategia estrategia</code> y un método <code>setEstrategia(Estrategia e)</code> que lo asigna.<br><strong>Resultado esperado:</strong> tres tipos (<code>Estrategia</code>, <code>Suma</code>, <code>Contexto</code>) que permiten cambiar el algoritmo del contexto (no imprime nada).', difficulty: 'hard', starterCode: '// Escribe tu programa completo aquí', solution: 'interface Estrategia {\n    int calcular(int a, int b);\n}\nclass Suma implements Estrategia {\n    public int calcular(int a, int b) { return a + b; }\n}\nclass Contexto {\n    private Estrategia estrategia;\n    public void setEstrategia(Estrategia e) { estrategia = e; }\n}', hint: 'Strategy permite cambiar el algoritmo en tiempo de ejecución.', validation: { requiredKeywords: ['interface', 'implements'] } },
    { id: 194, lessonId: 48, title: 'Decorator Pattern', description: '<strong>Qué hacer:</strong> Define la interfaz <code>Componente</code> con <code>String operar()</code> y la clase <code>Decorador</code> que <code>implements Componente</code>: guarda un <code>private Componente componente</code> recibido en su constructor y su <code>operar()</code> devuelve <code>"Decorado: " + componente.operar()</code>.<br><strong>Resultado esperado:</strong> si el componente envuelto devuelve <code>"hola"</code>, el <code>Decorador</code> devuelve <code>Decorado: hola</code> (no imprime nada por sí solo).', difficulty: 'hard', starterCode: '// Escribe tu programa completo aquí', solution: 'interface Componente {\n    String operar();\n}\nclass Decorador implements Componente {\n    private Componente componente;\n    public Decorador(Componente c) { componente = c; }\n    public String operar() {\n        return "Decorado: " + componente.operar();\n    }\n}', hint: 'Decorator envuelve un objeto para añadir funcionalidad.', validation: { requiredKeywords: ['implements', 'private'] } },
    { id: 195, lessonId: 50, title: 'SRP - Single Responsibility', description: '<strong>Qué hacer:</strong> Aplica la responsabilidad única declarando tres clases vacías separadas: <code>Usuario</code>, <code>UsuarioRepositorio</code> y <code>UsuarioValidator</code>. Agrega comentarios <code>//</code> que indiquen el diseño "Mal" (una clase con todo) y el "Bien" (clases separadas).<br><strong>Resultado esperado:</strong> tres clases vacías, cada una con una sola responsabilidad (no imprime nada).', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: '// Mal: clase con múltiples responsabilidades\n// Bien: separar en clases específicas\nclass Usuario { }\nclass UsuarioRepositorio { }\nclass UsuarioValidator { }', hint: 'SRP: cada clase debe tener una sola razón para cambiar.', validation: { requiredKeywords: ['class'] } },
    { id: 196, lessonId: 50, title: 'OCP - Open/Closed', description: '<strong>Qué hacer:</strong> Aplica abierto/cerrado: crea la clase <code>abstract class Forma</code> con el método abstracto <code>double area()</code>, y la clase <code>Circulo extends Forma</code> con el campo <code>double radio</code> y <code>area()</code> devolviendo <code>Math.PI * radio * radio</code>. Agrega un comentario que explique la idea.<br><strong>Resultado esperado:</strong> una jerarquía donde una nueva forma se agrega con otra subclase, sin modificar <code>Forma</code> (no imprime nada).', difficulty: 'hard', starterCode: '// Escribe tu programa completo aquí', solution: '// Abierto para extensión, cerrado para modificación\nabstract class Forma {\n    abstract double area();\n}\nclass Circulo extends Forma {\n    double radio;\n    double area() { return Math.PI * radio * radio; }\n}', hint: 'OCP: extender comportamiento sin modificar código existente.', validation: { requiredKeywords: ['abstract', 'extends'] } },
    { id: 197, lessonId: 50, title: 'LSP - Liskov Substitution', description: '<strong>Qué hacer:</strong> Declara <code>class Ave</code> con el método <code>void volar() { }</code> y agrega comentarios <code>//</code> que expliquen por qué un <code>Pinguino</code> no puede cumplir ese contrato ("Mal") y cómo se arregla separando <code>AveVoladora</code> y <code>AveNoVoladora</code> ("Bien").<br><strong>Resultado esperado:</strong> una clase <code>Ave</code> con <code>volar()</code> y comentarios que explican la violación de Liskov y su solución (no imprime nada).', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: '// Subtipos deben ser sustituibles por su tipo base\nclass Ave {\n    void volar() { }\n}\n// Mal: Pinguino no puede volar\n// Bien: separar en AveVoladora y AveNoVoladora', hint: 'LSP: los subtipos deben cumplir el contrato del tipo base.', validation: { requiredKeywords: ['class'] } },
    { id: 198, lessonId: 50, title: 'ISP - Interface Segregation', description: '<strong>Qué hacer:</strong> Aplica segregación de interfaces: declara dos interfaces pequeñas, <code>Imprimible</code> con <code>void imprimir();</code> y <code>Escaneable</code> con <code>void escanear();</code>. Agrega comentarios <code>//</code> "Mal" (una interfaz grande) y "Bien" (interfaces pequeñas).<br><strong>Resultado esperado:</strong> dos <code>interface</code> separadas con un método cada una (no imprime nada).', difficulty: 'medium', starterCode: '// Escribe tu código aquí', solution: '// Mal: interfaz grande\n// Bien: interfaces pequeñas y específicas\ninterface Imprimible {\n    void imprimir();\n}\ninterface Escaneable {\n    void escanear();\n}', hint: 'ISP: muchas interfaces específicas mejor que una general.', validation: { requiredKeywords: ['interface'] } },
    { id: 199, lessonId: 50, title: 'DIP - Dependency Inversion', description: '<strong>Qué hacer:</strong> Aplica inversión de dependencias: declara la <code>interface Repositorio</code> con <code>void guardar();</code> y la clase <code>Servicio</code> con un campo <code>private Repositorio repo</code> asignado por su constructor <code>public Servicio(Repositorio r)</code>. Agrega un comentario sobre depender de abstracciones.<br><strong>Resultado esperado:</strong> <code>Servicio</code> depende de la interfaz <code>Repositorio</code> y no de una clase concreta (no imprime nada).', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: '// Depender de abstracciones, no de concreciones\ninterface Repositorio {\n    void guardar();\n}\nclass Servicio {\n    private Repositorio repo;\n    public Servicio(Repositorio r) { repo = r; }\n}', hint: 'DIP: clases de alto nivel no deben depender de clases de bajo nivel.', validation: { requiredKeywords: ['interface', 'private'] } },
    { id: 200, lessonId: 52, title: 'JUnit Test', description: '<strong>Qué hacer:</strong> Dentro de una clase de pruebas (con <code>@Test</code> y <code>Assertions</code> ya importados), escribe un método de prueba llamado <code>testSuma</code> que calcule 2 + 2 en una variable <code>int</code> llamada <code>resultado</code> y verifique con <code>assertEquals</code> que vale 4.<br><strong>Resultado esperado:</strong> una prueba JUnit 5 que pasa (verde) porque 4 es igual a 4.', difficulty: 'medium', starterCode: 'import org.junit.jupiter.api.Test;\nimport static org.junit.jupiter.api.Assertions.*;', solution: '@Test\nvoid testSuma() {\n    int resultado = 2 + 2;\n    assertEquals(4, resultado);\n}', hint: '@Test marca un método de prueba. assertEquals verifica igualdad.', validation: { requiredKeywords: ['@Test', 'assertEquals'] } },
    { id: 201, lessonId: 52, title: 'JUnit BeforeEach', description: '<strong>Qué hacer:</strong> Escribe un método <code>setUp()</code>, sin retorno, con la anotación <code>@BeforeEach</code> y un comentario <code>// inicialización</code> dentro. JUnit lo ejecuta antes de cada prueba de la clase.<br><strong>Resultado esperado:</strong> un método <code>setUp()</code> anotado con <code>@BeforeEach</code>, sin retorno y con visibilidad de paquete.', difficulty: 'medium', starterCode: 'import org.junit.jupiter.api.BeforeEach;', solution: '@BeforeEach\nvoid setUp() {\n    // inicialización\n}', hint: '@BeforeEach se ejecuta antes de cada test.', validation: { requiredKeywords: ['@BeforeEach'] } },
    { id: 202, lessonId: 52, title: 'JUnit AssertThrows', description: '<strong>Qué hacer:</strong> Escribe un método de prueba (con <code>@Test</code>) llamado <code>testExcepcion</code> que use <code>assertThrows</code> para comprobar que un bloque lambda que lanza una <code>IllegalArgumentException</code> efectivamente la lanza.<br><strong>Resultado esperado:</strong> una prueba JUnit 5 que pasa porque el bloque lanza <code>IllegalArgumentException</code>.', difficulty: 'hard', starterCode: 'import static org.junit.jupiter.api.Assertions.*;', solution: '@Test\nvoid testExcepcion() {\n    assertThrows(IllegalArgumentException.class, () -> {\n        throw new IllegalArgumentException();\n    });\n}', hint: 'assertThrows verifica que se lance una excepción específica.', validation: { requiredKeywords: ['assertThrows'] } },
    { id: 203, lessonId: 52, title: 'Mockito Mock', description: '<strong>Qué hacer:</strong> Considera que existe una interfaz <code>Repositorio</code> con el método <code>String obtener()</code>. Con <code>Mockito.*</code> importado estáticamente, crea un mock llamado <code>mockRepo</code> de esa interfaz y configúralo con <code>when(...).thenReturn(...)</code> para que <code>obtener()</code> devuelva <code>"dato"</code>.<br><strong>Resultado esperado:</strong> <code>mockRepo.obtener()</code> devolverá <code>dato</code> (el fragmento no imprime nada).', difficulty: 'hard', starterCode: 'import static org.mockito.Mockito.*;', solution: 'Repositorio mockRepo = mock(Repositorio.class);\nwhen(mockRepo.obtener()).thenReturn("dato");', hint: 'mock() crea un objeto simulado. when().thenReturn() define comportamiento.', validation: { requiredKeywords: ['mock', 'when', 'thenReturn'] } },
    { id: 204, lessonId: 52, title: 'Mockito Verify', description: '<strong>Qué hacer:</strong> Considera que existe una interfaz <code>Repositorio</code> con <code>void guardar()</code>. Crea un mock llamado <code>mockRepo</code> de esa interfaz, llama a su método <code>guardar()</code> y comprueba con <code>verify</code> que se llamó exactamente una vez.<br><strong>Resultado esperado:</strong> la verificación pasa porque <code>guardar()</code> se invocó una vez (no imprime nada).', difficulty: 'medium', starterCode: 'import static org.mockito.Mockito.*;', solution: 'Repositorio mockRepo = mock(Repositorio.class);\nmockRepo.guardar();\nverify(mockRepo).guardar();', hint: 'verify() comprueba que un método fue llamado.', validation: { requiredKeywords: ['verify'] } },
    { id: 205, lessonId: 51, title: 'TDD Red-Green-Refactor', description: '<strong>Qué hacer:</strong> Escribe las tres fases con comentarios <code>// 1. Red</code>, <code>// 2. Green</code> y <code>// 3. Refactor</code>. En Red, un método <code>@Test void testSuma()</code> que use <code>assertEquals(4, suma(2, 2))</code>; en Green, el método mínimo <code>int suma(int a, int b) { return a + b; }</code>; en Refactor, un comentario sobre cómo mejorarías el código.<br><strong>Resultado esperado:</strong> la prueba de la fase Red falla mientras <code>suma</code> no exista, y pasa tras la fase Green (no imprime nada).', difficulty: 'hard', starterCode: '// Escribe tu código aquí', solution: '// 1. Red: escribe test que falla\n@Test void testFalla() { assertEquals(5, suma(2,2)); }\n// 2. Green: implementa mínimo para pasar\nint suma(int a, int b) { return a + b; }\n// 3. Refactor: mejora el código', hint: 'TDD: primero test (rojo), luego código (verde), finalmente refactorizar.', validation: { requiredKeywords: ['@Test'] } },
    { id: 206, lessonId: 52, title: 'AssertJ Fluent', description: '<strong>Qué hacer:</strong> Con <code>Assertions.*</code> de AssertJ importado, declara un <code>String</code> llamado <code>texto</code> con el valor <code>"Hola"</code> y escribe una aserción encadenada con <code>assertThat</code> que verifique que no es nulo, que empieza con <code>"H"</code> y que tiene 4 caracteres.<br><strong>Resultado esperado:</strong> la aserción pasa: <code>Hola</code> no es nulo, empieza con <code>H</code> y tiene 4 caracteres.', difficulty: 'medium', starterCode: 'import static org.assertj.core.api.Assertions.*;', solution: 'String texto = "Hola";\nassertThat(texto)\n    .isNotNull()\n    .startsWith("H")\n    .hasSize(4);', hint: 'AssertJ permite aserciones encadenadas y legibles.', validation: { requiredKeywords: ['assertThat'] } },
    { id: 207, lessonId: 52, title: 'Parametrized Test', description: '<strong>Qué hacer:</strong> Escribe un método <code>testMultiple(int numero)</code> anotado con <code>@ParameterizedTest</code> y con <code>@ValueSource</code> que reciba los enteros 1, 2 y 3, y que verifique con <code>assertTrue</code> que el número es mayor que 0 (agrega <code>import static org.junit.jupiter.api.Assertions.*;</code>).<br><strong>Resultado esperado:</strong> la prueba se ejecuta tres veces (con 1, 2 y 3) y las tres pasan.', difficulty: 'hard', starterCode: 'import org.junit.jupiter.params.ParameterizedTest;\nimport org.junit.jupiter.params.provider.ValueSource;', solution: '@ParameterizedTest\n@ValueSource(ints = {1, 2, 3})\nvoid testMultiple(int numero) {\n    assertTrue(numero > 0);\n}', hint: '@ParameterizedTest ejecuta el test con múltiples valores.', validation: { requiredKeywords: ['@ParameterizedTest', '@ValueSource'] } },
    { id: 208, lessonId: 52, title: 'Test Coverage', description: '<strong>Qué hacer:</strong> Escribe solo comentarios <code>//</code> sobre cobertura: que se mide con JaCoCo, que un objetivo habitual es más de 80 %, que se cubren líneas, ramas y métodos, y el comando <code>mvn test jacoco:report</code>.<br><strong>Resultado esperado:</strong> solo comentarios (no hay código ni salida); deben mencionar el comando <code>mvn test jacoco:report</code>.', difficulty: 'medium', starterCode: '// Escribe tu respuesta aquí', solution: '// Usa herramientas como JaCoCo\n// Objetivo: >80% de cobertura\n// Cubre: líneas, ramas, métodos\n// mvn test jacoco:report', hint: 'Cobertura mide qué porcentaje del código es ejecutado por tests.', validation: { requiredKeywords: ['test'] } }
];

